import * as THREE from 'three'

export const TAU = Math.PI * 2
export const clamp = (v, a, b) => Math.min(b, Math.max(a, v))
export const lerp = (a, b, t) => a + (b - a) * t
export const invLerp = (a, b, v) => (v - a) / (b - a)
export const smoothstep = (a, b, x) => {
  const t = clamp((x - a) / (b - a), 0, 1)
  return t * t * (3 - 2 * t)
}
export const damp = (a, b, lambda, dt) => lerp(a, b, 1 - Math.exp(-lambda * dt))
export const rand = (a = 0, b = 1) => a + Math.random() * (b - a)
export const randInt = (a, b) => Math.floor(rand(a, b + 1))
export const chance = (p) => Math.random() < p
export const pick = (arr) => arr[Math.floor(Math.random() * arr.length)]
export const randSign = () => (Math.random() < 0.5 ? -1 : 1)
export const easeOutCubic = (t) => 1 - Math.pow(1 - t, 3)
export const easeInCubic = (t) => t * t * t
export const easeOutQuint = (t) => 1 - Math.pow(1 - t, 5)
export const easeInOutQuad = (t) => (t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2)
export const easeOutBack = (t) => {
  const c1 = 1.70158
  const c3 = c1 + 1
  return 1 + c3 * Math.pow(t - 1, 3) + c1 * Math.pow(t - 1, 2)
}

export function roman(n) {
  const map = [
    [1000, 'M'], [900, 'CM'], [500, 'D'], [400, 'CD'], [100, 'C'], [90, 'XC'],
    [50, 'L'], [40, 'XL'], [10, 'X'], [9, 'IX'], [5, 'V'], [4, 'IV'], [1, 'I']
  ]
  let out = ''
  for (const [v, s] of map) while (n >= v) { out += s; n -= v }
  return out
}

export function makeCanvas(w, h) {
  const c = document.createElement('canvas')
  c.width = w
  c.height = h
  return c
}

function rng(seed) {
  let s = seed >>> 0
  return () => {
    s = (s * 1664525 + 1013904223) >>> 0
    return s / 4294967296
  }
}

function grain(ctx, w, h, amount, size = 1, alpha = 0.1) {
  const data = ctx.getImageData(0, 0, w, h)
  for (let i = 0; i < data.data.length; i += 4) {
    const n = (Math.random() - 0.5) * amount
    data.data[i] += n
    data.data[i + 1] += n
    data.data[i + 2] += n
  }
  ctx.putImageData(data, 0, 0)
}

export function sandTexture(renderer) {
  const s = 512
  const c = makeCanvas(s, s)
  const ctx = c.getContext('2d')
  const r = rng(7)
  const g = ctx.createLinearGradient(0, 0, s, s)
  g.addColorStop(0, '#8a7150')
  g.addColorStop(0.5, '#79613f')
  g.addColorStop(1, '#5f4c34')
  ctx.fillStyle = g
  ctx.fillRect(0, 0, s, s)
  for (let i = 0; i < 4200; i++) {
    const x = r() * s, y = r() * s
    const v = 40 + r() * 80
    ctx.fillStyle = `rgba(${v + 40},${v + 26},${v + 4},${0.08 + r() * 0.25})`
    ctx.fillRect(x, y, 1 + r() * 2.2, 1 + r() * 2)
  }
  for (let i = 0; i < 120; i++) {
    const x = r() * s, y = r() * s, rr = 0.6 + r() * 2.4
    ctx.fillStyle = r() > 0.5 ? 'rgba(30,22,14,.4)' : 'rgba(210,190,155,.25)'
    ctx.beginPath(); ctx.arc(x, y, rr, 0, TAU); ctx.fill()
  }
  for (let i = 0; i < 14; i++) {
    ctx.strokeStyle = `rgba(40,28,16,${0.12 + r() * 0.16})`
    ctx.lineWidth = 0.8 + r() * 1.4
    ctx.beginPath()
    let x = r() * s, y = r() * s
    ctx.moveTo(x, y)
    for (let k = 0; k < 5; k++) { x += (r() - 0.5) * 60; y += r() * 34; ctx.lineTo(x, y) }
    ctx.stroke()
  }
  grain(ctx, s, s, 20)
  const t = new THREE.CanvasTexture(c)
  t.wrapS = t.wrapT = THREE.RepeatWrapping
  t.repeat.set(9, 9)
  t.colorSpace = THREE.SRGBColorSpace
  t.anisotropy = Math.min(8, renderer?.capabilities.getMaxAnisotropy?.() || 1)
  return t
}

export function stoneTexture(renderer) {
  const w = 512, h = 512
  const c = makeCanvas(w, h)
  const ctx = c.getContext('2d')
  const r = rng(19)
  ctx.fillStyle = '#3c3733'
  ctx.fillRect(0, 0, w, h)
  const rows = 8
  const rh = h / rows
  for (let row = 0; row < rows; row++) {
    const offset = (row % 2) * 42
    for (let x = -42; x < w; x += 84) {
      const g = 36 + r() * 22
      ctx.fillStyle = `rgb(${g + 8},${g + 2},${g - 2})`
      ctx.fillRect(x + offset + 2, row * rh + 2, 84 - 4, rh - 4)
      ctx.strokeStyle = 'rgba(12,9,7,.7)'
      ctx.lineWidth = 2
      ctx.strokeRect(x + offset + 2, row * rh + 2, 84 - 4, rh - 4)
      for (let k = 0; k < 20; k++) {
        ctx.fillStyle = `rgba(${150 + r() * 50},${145 + r() * 45},${130 + r() * 40},${r() * 0.09})`
        ctx.fillRect(x + offset + r() * 80, row * rh + r() * rh, 2 + r() * 8, 1 + r() * 2)
      }
    }
  }
  grain(ctx, w, h, 26)
  const t = new THREE.CanvasTexture(c)
  t.wrapS = t.wrapT = THREE.RepeatWrapping
  t.repeat.set(6, 2)
  t.colorSpace = THREE.SRGBColorSpace
  t.anisotropy = Math.min(8, renderer?.capabilities.getMaxAnisotropy?.() || 1)
  return t
}

export function bloodSplatTexture() {
  const s = 256
  const c = makeCanvas(s, s)
  const ctx = c.getContext('2d')
  ctx.clearRect(0, 0, s, s)
  const r = rng(51)
  const cx = s / 2, cy = s / 2
  // central pool
  ctx.fillStyle = 'rgba(105,6,10,0.96)'
  ctx.beginPath()
  for (let i = 0; i <= 32; i++) {
    const a = (i / 32) * TAU
    const rad = 42 + Math.sin(a * 3 + 1) * 11 + r() * 12
    const x = cx + Math.cos(a) * rad, y = cy + Math.sin(a) * rad
    i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y)
  }
  ctx.closePath(); ctx.fill()
  // drops and spatter
  for (let i = 0; i < 90; i++) {
    const a = r() * TAU
    const d = 30 + Math.pow(r(), 0.6) * 88
    const rr = 1 + Math.pow(r(), 3) * 10
    const x = cx + Math.cos(a) * d, y = cy + Math.sin(a) * d
    ctx.fillStyle = `rgba(${70 + r() * 60},${2 + r() * 10},${4 + r() * 12},${0.55 + r() * 0.4})`
    ctx.beginPath(); ctx.ellipse(x, y, rr, rr * (0.5 + r()), a, 0, TAU); ctx.fill()
  }
  // streaks
  for (let i = 0; i < 9; i++) {
    const a = r() * TAU
    ctx.strokeStyle = `rgba(90,4,8,${0.3 + r() * 0.35})`
    ctx.lineWidth = 2 + r() * 5
    ctx.beginPath()
    ctx.moveTo(cx + Math.cos(a) * 24, cy + Math.sin(a) * 24)
    ctx.lineTo(cx + Math.cos(a) * (50 + r() * 50), cy + Math.sin(a) * (50 + r() * 50))
    ctx.stroke()
  }
  const t = new THREE.CanvasTexture(c)
  t.colorSpace = THREE.SRGBColorSpace
  return t
}

export function softDropTexture() {
  const s = 64
  const c = makeCanvas(s, s)
  const ctx = c.getContext('2d')
  const g = ctx.createRadialGradient(s / 2, s / 2, 0, s / 2, s / 2, s / 2)
  g.addColorStop(0, 'rgba(255,255,255,1)')
  g.addColorStop(0.45, 'rgba(255,255,255,0.85)')
  g.addColorStop(0.8, 'rgba(255,255,255,0.25)')
  g.addColorStop(1, 'rgba(255,255,255,0)')
  ctx.fillStyle = g
  ctx.fillRect(0, 0, s, s)
  const t = new THREE.CanvasTexture(c)
  return t
}

export function flameTexture() {
  const s = 128
  const c = makeCanvas(s, s)
  const ctx = c.getContext('2d')
  const g = ctx.createRadialGradient(s / 2, s / 2, 2, s / 2, s / 2, s / 2)
  g.addColorStop(0, 'rgba(255,246,210,1)')
  g.addColorStop(0.18, 'rgba(255,197,90,0.95)')
  g.addColorStop(0.45, 'rgba(255,105,20,0.6)')
  g.addColorStop(0.75, 'rgba(190,30,10,0.12)')
  g.addColorStop(1, 'rgba(120,10,0,0)')
  ctx.fillStyle = g
  ctx.beginPath(); ctx.arc(s / 2, s / 2, s / 2, 0, TAU); ctx.fill()
  const t = new THREE.CanvasTexture(c)
  t.colorSpace = THREE.SRGBColorSpace
  return t
}

export function bannerTexture() {
  const w = 256, h = 512
  const c = makeCanvas(w, h)
  const ctx = c.getContext('2d')
  const g = ctx.createLinearGradient(0, 0, 0, h)
  g.addColorStop(0, '#5c0910')
  g.addColorStop(0.65, '#3e050b')
  g.addColorStop(1, '#260307')
  ctx.fillStyle = g
  ctx.fillRect(0, 0, w, h)
  for (let i = 0; i < 400; i++) {
    ctx.fillStyle = `rgba(0,0,0,${Math.random() * 0.18})`
    ctx.fillRect(Math.random() * w, Math.random() * h, 1 + Math.random() * 3, 1 + Math.random() * 3)
  }
  ctx.strokeStyle = 'rgba(201,161,92,.55)'
  ctx.lineWidth = 5
  ctx.strokeRect(16, 16, w - 32, h - 32)
  ctx.strokeStyle = 'rgba(201,161,92,.25)'
  ctx.lineWidth = 2
  ctx.strokeRect(27, 27, w - 54, h - 54)
  // crown / skull emblem
  ctx.save()
  ctx.translate(w / 2, 190)
  ctx.fillStyle = 'rgba(201,161,92,.82)'
  ctx.beginPath()
  ctx.moveTo(-52, -42); ctx.lineTo(-52, 26); ctx.lineTo(-30, 6); ctx.lineTo(-14, 34)
  ctx.lineTo(0, -6); ctx.lineTo(14, 34); ctx.lineTo(30, 6); ctx.lineTo(52, 26); ctx.lineTo(52, -42)
  ctx.closePath(); ctx.fill()
  // skull
  ctx.fillStyle = 'rgba(228,216,196,.9)'
  ctx.beginPath(); ctx.ellipse(0, 86, 33, 40, 0, 0, TAU); ctx.fill()
  ctx.fillRect(-21, 110, 42, 26)
  ctx.fillStyle = '#2a0408'
  ctx.beginPath(); ctx.ellipse(-13, 82, 9, 11, 0, 0, TAU); ctx.fill()
  ctx.beginPath(); ctx.ellipse(13, 82, 9, 11, 0, 0, TAU); ctx.fill()
  ctx.fillRect(-6, 100, 12, 14)
  ctx.fillStyle = 'rgba(201,161,92,.7)'
  for (let i = -2; i <= 2; i++) ctx.fillRect(i * 9 - 2, 124, 4, 14)
  ctx.restore()
  // drips
  for (let i = 0; i < 26; i++) {
    const x = 30 + Math.random() * (w - 60)
    const y = 300 + Math.random() * 40
    const len = 20 + Math.random() * 130
    ctx.fillStyle = `rgba(90,4,8,${0.2 + Math.random() * 0.35})`
    ctx.fillRect(x, y, 2 + Math.random() * 4, len)
    ctx.beginPath(); ctx.arc(x + 2, y + len, 3 + Math.random() * 3, 0, TAU); ctx.fill()
  }
  const t = new THREE.CanvasTexture(c)
  t.colorSpace = THREE.SRGBColorSpace
  return t
}

export function emblemTexture() {
  const s = 128
  const c = makeCanvas(s, s)
  const ctx = c.getContext('2d')
  ctx.clearRect(0, 0, s, s)
  ctx.fillStyle = '#d8cdb8'
  // simple skull-ish mark
  ctx.beginPath(); ctx.ellipse(64, 54, 26, 30, 0, 0, TAU); ctx.fill()
  ctx.fillRect(46, 72, 36, 26)
  ctx.fillStyle = '#1a0406'
  ctx.beginPath(); ctx.ellipse(54, 50, 7, 9, 0, 0, TAU); ctx.fill()
  ctx.beginPath(); ctx.ellipse(74, 50, 7, 9, 0, 0, TAU); ctx.fill()
  ctx.fillRect(60, 64, 8, 12)
  const t = new THREE.CanvasTexture(c)
  t.colorSpace = THREE.SRGBColorSpace
  return t
}

export function makeMat(color, opts = {}) {
  return new THREE.MeshStandardMaterial({ color, roughness: 0.85, metalness: 0.05, ...opts })
}

export function makeMesh(geo, mat, pos, rot) {
  const m = new THREE.Mesh(geo, mat)
  if (pos) m.position.set(pos[0], pos[1], pos[2])
  if (rot) m.rotation.set(rot[0], rot[1], rot[2])
  m.castShadow = true
  m.receiveShadow = true
  return m
}

export function segmentPointDistance(p, a, b) {
  const abx = b.x - a.x, aby = b.y - a.y, abz = b.z - a.z
  const apx = p.x - a.x, apy = p.y - a.y, apz = p.z - a.z
  const denom = abx * abx + aby * aby + abz * abz
  let t = denom > 1e-8 ? (apx * abx + apy * aby + apz * abz) / denom : 0
  t = clamp(t, 0, 1)
  const dx = apx - abx * t, dy = apy - aby * t, dz = apz - abz * t
  return Math.sqrt(dx * dx + dy * dy + dz * dz)
}

export function disposeObject(obj) {
  obj.traverse((o) => {
    if (o.geometry) o.geometry.dispose()
    if (o.material) {
      if (Array.isArray(o.material)) o.material.forEach((m) => m.dispose())
      else o.material.dispose()
    }
  })
}

import { clamp, rand } from './utils.js'

/**
 * Fully procedural audio — no external samples.
 * Everything is synthesised from noise buffers and oscillators on first gesture.
 */
export class Sound {
  constructor() {
    this.ctx = null
    this.master = null
    this.ready = false
    this.muted = false
    this.crowdGain = null
    this.ambientGain = null
    this.lastHit = 0
    this.lastSwing = 0
  }

  init() {
    if (this.ready) { this.resume(); return }
    const AC = window.AudioContext || window.webkitAudioContext
    if (!AC) return
    try {
      const ctx = new AC()
      this.ctx = ctx
      const comp = ctx.createDynamicsCompressor()
      comp.threshold.value = -16
      comp.knee.value = 22
      comp.ratio.value = 5
      comp.attack.value = 0.003
      comp.release.value = 0.22
      this.master = ctx.createGain()
      this.master.gain.value = 0.75
      this.master.connect(comp)
      comp.connect(ctx.destination)

      // shared noise
      const len = ctx.sampleRate * 2
      const buf = ctx.createBuffer(1, len, ctx.sampleRate)
      const data = buf.getChannelData(0)
      for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1
      this.noiseBuf = buf
      this.ready = true
      this.startAmbience()
      this.resume()
    } catch {
      this.ready = false
    }
  }

  resume() {
    if (this.ctx && this.ctx.state === 'suspended') this.ctx.resume().catch(() => {})
  }

  setMuted(m) {
    this.muted = m
    if (this.master) this.master.gain.setTargetAtTime(m ? 0 : 0.75, this.ctx.currentTime, 0.05)
  }

  now() { return this.ctx.currentTime }

  noise(dur = 0.3, type = 'bandpass', freq = 800, q = 1, gain = 0.3, when = 0, sweep = 0) {
    if (!this.ready) return null
    const ctx = this.ctx
    const t = ctx.currentTime + when
    const src = ctx.createBufferSource()
    src.buffer = this.noiseBuf
    src.loop = true
    src.playbackRate.value = rand(0.85, 1.15)
    const f = ctx.createBiquadFilter()
    f.type = type
    f.frequency.setValueAtTime(freq, t)
    if (sweep) f.frequency.exponentialRampToValueAtTime(Math.max(30, sweep), t + dur)
    f.Q.value = q
    const g = ctx.createGain()
    g.gain.setValueAtTime(0.0001, t)
    g.gain.exponentialRampToValueAtTime(gain, t + 0.012)
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur)
    src.connect(f); f.connect(g); g.connect(this.master)
    src.start(t); src.stop(t + dur + 0.02)
    return { src, f, g }
  }

  tone(type = 'sine', f0 = 220, f1 = 80, dur = 0.2, gain = 0.25, when = 0, curve = 'exp') {
    if (!this.ready) return
    const ctx = this.ctx
    const t = ctx.currentTime + when
    const o = ctx.createOscillator()
    o.type = type
    o.frequency.setValueAtTime(f0, t)
    if (curve === 'exp') o.frequency.exponentialRampToValueAtTime(Math.max(12, f1), t + dur)
    else o.frequency.linearRampToValueAtTime(Math.max(12, f1), t + dur)
    const g = ctx.createGain()
    g.gain.setValueAtTime(0.0001, t)
    g.gain.exponentialRampToValueAtTime(gain, t + 0.008)
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur)
    o.connect(g); g.connect(this.master)
    o.start(t); o.stop(t + dur + 0.02)
    return { o, g }
  }

  startAmbience() {
    if (!this.ready) return
    const ctx = this.ctx
    // wind
    const wind = ctx.createBufferSource()
    wind.buffer = this.noiseBuf
    wind.loop = true
    const wf = ctx.createBiquadFilter()
    wf.type = 'lowpass'
    wf.frequency.value = 260
    wf.Q.value = 0.5
    const wg = ctx.createGain()
    wg.gain.value = 0.05
    const lfo = ctx.createOscillator()
    lfo.frequency.value = 0.09
    const lfoG = ctx.createGain()
    lfoG.gain.value = 0.02
    lfo.connect(lfoG); lfoG.connect(wg.gain)
    wind.connect(wf); wf.connect(wg); wg.connect(this.master)
    wind.start(); lfo.start()
    this.ambientGain = wg

    // crowd murmur
    const crowd = ctx.createBufferSource()
    crowd.buffer = this.noiseBuf
    crowd.loop = true
    crowd.playbackRate.value = 0.7
    const cf = ctx.createBiquadFilter()
    cf.type = 'bandpass'
    cf.frequency.value = 560
    cf.Q.value = 0.7
    const cf2 = ctx.createBiquadFilter()
    cf2.type = 'peaking'
    cf2.frequency.value = 1200
    cf2.gain.value = 6
    const cg = ctx.createGain()
    cg.gain.value = 0.018
    const clfo = ctx.createOscillator()
    clfo.frequency.value = 0.17
    const clfoG = ctx.createGain()
    clfoG.gain.value = 0.008
    clfo.connect(clfoG); clfoG.connect(cg.gain)
    crowd.connect(cf); cf.connect(cf2); cf2.connect(cg); cg.connect(this.master)
    crowd.start(); clfo.start()
    this.crowdGain = cg
  }

  crowdRoar(power = 1, dur = 1.8) {
    if (!this.ready) return
    const ctx = this.ctx
    const t = ctx.currentTime
    const target = clamp(0.03 + power * 0.09, 0.02, 0.2)
    this.crowdGain.gain.cancelScheduledValues(t)
    this.crowdGain.gain.setValueAtTime(this.crowdGain.gain.value, t)
    this.crowdGain.gain.linearRampToValueAtTime(target, t + 0.18)
    this.crowdGain.gain.exponentialRampToValueAtTime(0.018, t + dur)
    // surface noise swell
    this.noise(dur * 0.8, 'bandpass', 900, 0.6, 0.05, 0, 400)
    this.tone('sawtooth', rand(120, 180), rand(90, 140), 0.5, 0.015, 0.02)
  }

  swing(kind = 'sword', charge = 0) {
    if (!this.ready) return
    const t = this.now()
    if (t - this.lastSwing < 0.07) return
    this.lastSwing = t
    if (kind === 'hammer') {
      this.noise(0.26, 'bandpass', 420, 1.2, 0.22 + charge * 0.15, 0, 130)
      this.tone('sine', 110, 45, 0.22, 0.08 + charge * 0.08)
    } else {
      this.noise(0.18, 'bandpass', 1300 + charge * 900, 1.6, 0.18 + charge * 0.1, 0, 420)
      this.tone('triangle', 620, 240, 0.12, 0.025)
    }
  }

  hitFlesh(power = 1) {
    if (!this.ready) return
    this.noise(0.16, 'lowpass', 900 + power * 600, 0.9, 0.35 * power, 0, 180)
    this.tone('sine', 95, 38, 0.16, 0.22 * power)
    this.tone('square', 180, 60, 0.05, 0.04 * power)
  }

  hitBone(power = 1) {
    if (!this.ready) return
    this.noise(0.07, 'highpass', 1800, 1, 0.18 * power)
    this.tone('square', 320, 90, 0.06, 0.06 * power)
    for (let i = 0; i < 4; i++) this.noise(0.03, 'bandpass', rand(1200, 3000), 3, 0.06 * power, rand(0, 0.05))
  }

  metal() {
    if (!this.ready) return
    this.noise(0.09, 'highpass', 2400, 1, 0.2)
    this.tone('triangle', 1450, 900, 0.22, 0.05)
    this.tone('triangle', 2200, 1500, 0.16, 0.03)
  }

  block() {
    if (!this.ready) return
    this.metal()
    this.tone('square', 380, 150, 0.1, 0.08)
  }

  parry() {
    if (!this.ready) return
    this.metal()
    this.tone('sine', 2600, 1800, 0.5, 0.06)
    this.tone('sine', 3900, 3000, 0.4, 0.035)
    this.noise(0.2, 'highpass', 3000, 1, 0.1)
  }

  sever() {
    if (!this.ready) return
    this.hitFlesh(1.3)
    this.hitBone(1.1)
    this.noise(0.34, 'lowpass', 1500, 1.4, 0.24, 0.03, 220)
    this.tone('sine', 210, 65, 0.32, 0.1, 0.02)
    // wet squelch
    this.noise(0.22, 'bandpass', 600, 4, 0.12, 0.06, 240)
  }

  crush() {
    if (!this.ready) return
    this.tone('sine', 80, 28, 0.34, 0.4)
    this.noise(0.3, 'lowpass', 700, 1, 0.4, 0, 120)
    this.hitBone(1.4)
    this.noise(0.4, 'bandpass', 500, 3, 0.18, 0.05, 180)
  }

  scream(pitch = 1) {
    if (!this.ready) return
    const ctx = this.ctx
    const t = ctx.currentTime
    const o = ctx.createOscillator()
    o.type = 'sawtooth'
    o.frequency.setValueAtTime(rand(180, 260) * pitch, t)
    o.frequency.linearRampToValueAtTime(rand(300, 430) * pitch, t + 0.16)
    o.frequency.linearRampToValueAtTime(rand(140, 190) * pitch, t + 0.65)
    const vib = ctx.createOscillator()
    vib.frequency.value = rand(5, 8)
    const vg = ctx.createGain()
    vg.gain.value = 14
    vib.connect(vg); vg.connect(o.frequency)
    const f1 = ctx.createBiquadFilter()
    f1.type = 'bandpass'; f1.frequency.value = 750 * pitch; f1.Q.value = 4
    const f2 = ctx.createBiquadFilter()
    f2.type = 'bandpass'; f2.frequency.value = 1350 * pitch; f2.Q.value = 6
    const g = ctx.createGain()
    g.gain.setValueAtTime(0.0001, t)
    g.gain.exponentialRampToValueAtTime(0.06, t + 0.05)
    g.gain.setValueAtTime(0.06, t + 0.4)
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.7)
    o.connect(f1); o.connect(f2); f1.connect(g); f2.connect(g); g.connect(this.master)
    o.start(t); vib.start(t); o.stop(t + 0.72); vib.stop(t + 0.72)
  }

  deathRattle() {
    if (!this.ready) return
    this.noise(0.55, 'lowpass', 600, 1, 0.12, 0, 160)
    this.tone('sawtooth', 140, 55, 0.5, 0.03)
  }

  playerHurt() {
    if (!this.ready) return
    this.hitFlesh(1.1)
    this.tone('sawtooth', 150, 85, 0.22, 0.045)
    this.noise(0.25, 'bandpass', 800, 1.2, 0.1, 0.02, 300)
  }

  dodge() {
    if (!this.ready) return
    this.noise(0.22, 'bandpass', 700, 0.8, 0.12, 0, 250)
  }

  whooshHeavy() {
    if (!this.ready) return
    this.noise(0.35, 'bandpass', 260, 0.8, 0.2, 0, 90)
  }

  pickup() {
    if (!this.ready) return
    this.metal()
    this.tone('triangle', 880, 1320, 0.12, 0.05)
  }

  ui() {
    if (!this.ready) return
    this.tone('triangle', 520, 330, 0.07, 0.04)
  }

  heartbeat(intensity = 1) {
    if (!this.ready) return
    this.tone('sine', 62, 34, 0.17, 0.2 * intensity)
    this.tone('sine', 55, 30, 0.2, 0.13 * intensity, 0.2)
  }

  step() {
    if (!this.ready) return
    this.noise(0.06, 'lowpass', 320, 0.7, 0.035)
  }

  bossRoar() {
    if (!this.ready) return
    const ctx = this.ctx
    const t = ctx.currentTime
    const o = ctx.createOscillator()
    o.type = 'sawtooth'
    o.frequency.setValueAtTime(70, t)
    o.frequency.linearRampToValueAtTime(120, t + 0.4)
    o.frequency.linearRampToValueAtTime(50, t + 1.4)
    const f = ctx.createBiquadFilter()
    f.type = 'lowpass'; f.frequency.value = 400
    const g = ctx.createGain()
    g.gain.setValueAtTime(0.0001, t)
    g.gain.exponentialRampToValueAtTime(0.18, t + 0.15)
    g.gain.exponentialRampToValueAtTime(0.0001, t + 1.5)
    o.connect(f); f.connect(g); g.connect(this.master)
    o.start(t); o.stop(t + 1.55)
    this.crowdRoar(1.4, 2.4)
    this.noise(1.2, 'lowpass', 240, 0.8, 0.12, 0, 100)
  }
}

export const sound = new Sound()

import * as THREE from 'three'
import {
  TAU, clamp, rand, randInt, chance, makeMat, makeMesh,
  sandTexture, stoneTexture, bannerTexture, flameTexture, emblemTexture, softDropTexture
} from './utils.js'

export const ARENA_RADIUS = 23.5

function skyMaterial() {
  return new THREE.ShaderMaterial({
    side: THREE.BackSide,
    depthWrite: false,
    fog: false,
    uniforms: {
      top: { value: new THREE.Color(0x05060c) },
      mid: { value: new THREE.Color(0x1b0a12) },
      horizon: { value: new THREE.Color(0x4a1014) },
      bottom: { value: new THREE.Color(0x090405) }
    },
    vertexShader: /* glsl */`
      varying vec3 vWorld;
      void main() {
        vec4 wp = modelMatrix * vec4(position, 1.0);
        vWorld = wp.xyz;
        gl_Position = projectionMatrix * viewMatrix * wp;
      }
    `,
    fragmentShader: /* glsl */`
      uniform vec3 top; uniform vec3 mid; uniform vec3 horizon; uniform vec3 bottom;
      varying vec3 vWorld;
      void main() {
        float h = normalize(vWorld).y;
        vec3 c = mix(horizon, mid, smoothstep(-0.02, 0.18, h));
        c = mix(c, top, smoothstep(0.14, 0.65, h));
        c = mix(bottom, c, smoothstep(-0.35, -0.01, h));
        float glow = exp(-abs(h) * 9.0);
        c += vec3(0.16, 0.025, 0.02) * glow;
        gl_FragColor = vec4(c, 1.0);
      }
    `
  })
}

export class Arena {
  constructor(scene, renderer, lowQuality = false) {
    this.scene = scene
    this.renderer = renderer
    this.low = lowQuality
    this.time = 0
    this.crowdEnergy = 0
    this.embers = []
    this.flames = []
    this.banners = []
    this.spawnPoints = []
    this.crowd = null
    this.crowdHeads = null
    this.crowdBase = []
    this._tmpM = new THREE.Matrix4()
    this._tmpQ = new THREE.Quaternion()
    this._tmpE = new THREE.Euler()
    this._tmpV = new THREE.Vector3()
    this._tmpS = new THREE.Vector3()

    this.buildSky()
    this.buildFloor()
    this.buildStands()
    this.buildCrowd()
    this.buildPillars()
    this.buildGates()
    this.buildProps()
    this.buildLights()
    this.buildDust()
  }

  buildSky() {
    const sky = new THREE.Mesh(new THREE.SphereGeometry(220, 32, 20), skyMaterial())
    sky.frustumCulled = false
    this.scene.add(sky)

    // moon
    const moonCanvas = document.createElement('canvas')
    moonCanvas.width = moonCanvas.height = 128
    const mc = moonCanvas.getContext('2d')
    const mg = mc.createRadialGradient(64, 64, 18, 64, 64, 64)
    mg.addColorStop(0, 'rgba(240,232,215,0.95)')
    mg.addColorStop(0.55, 'rgba(210,196,175,0.5)')
    mg.addColorStop(1, 'rgba(120,80,70,0)')
    mc.fillStyle = mg
    mc.fillRect(0, 0, 128, 128)
    const moonTex = new THREE.CanvasTexture(moonCanvas)
    moonTex.colorSpace = THREE.SRGBColorSpace
    const moon = new THREE.Sprite(new THREE.SpriteMaterial({
      map: moonTex, transparent: true, depthWrite: false, fog: false, color: 0xffe9cf
    }))
    moon.position.set(-105, 75, -150)
    moon.scale.set(48, 48, 1)
    this.scene.add(moon)

    // stars
    const count = 500
    const positions = new Float32Array(count * 3)
    const colors = new Float32Array(count * 3)
    for (let i = 0; i < count; i++) {
      const a = rand(0, TAU)
      const y = rand(0.08, 1)
      const r = Math.sqrt(1 - y * y)
      positions[i * 3] = Math.cos(a) * r * 195
      positions[i * 3 + 1] = y * 195
      positions[i * 3 + 2] = Math.sin(a) * r * 195
      const w = rand(0.55, 1)
      colors[i * 3] = w
      colors[i * 3 + 1] = w * rand(0.85, 0.98)
      colors[i * 3 + 2] = w * rand(0.8, 1)
    }
    const g = new THREE.BufferGeometry()
    g.setAttribute('position', new THREE.BufferAttribute(positions, 3))
    g.setAttribute('color', new THREE.BufferAttribute(colors, 3))
    const stars = new THREE.Points(g, new THREE.PointsMaterial({
      size: 0.9, sizeAttenuation: true, vertexColors: true, transparent: true, opacity: 0.85,
      depthWrite: false, fog: false
    }))
    this.scene.add(stars)
  }

  buildFloor() {
    const sand = sandTexture(this.renderer)
    const floorMat = new THREE.MeshStandardMaterial({
      map: sand, color: 0x9a8a72, roughness: 0.97, metalness: 0
    })
    const floor = new THREE.Mesh(new THREE.CircleGeometry(ARENA_RADIUS + 1.4, 96), floorMat)
    floor.rotation.x = -Math.PI / 2
    floor.receiveShadow = true
    this.scene.add(floor)
    this.floor = floor

    // packed earth ring around the wall
    const outer = new THREE.Mesh(
      new THREE.RingGeometry(ARENA_RADIUS + 1.2, 29.5, 80),
      new THREE.MeshStandardMaterial({ color: 0x2f241a, roughness: 1 })
    )
    outer.rotation.x = -Math.PI / 2
    outer.position.y = -0.02
    outer.receiveShadow = true
    this.scene.add(outer)

    // dark old stains baked into the sand near the edges
    const stainMat = new THREE.MeshBasicMaterial({
      map: sandTexture(this.renderer), color: 0x3a1a12, transparent: true, opacity: 0.3,
      depthWrite: false
    })
    for (let i = 0; i < 10; i++) {
      const m = new THREE.Mesh(new THREE.CircleGeometry(rand(1.2, 3.4), 18), stainMat)
      const a = rand(0, TAU), r = rand(6, ARENA_RADIUS - 2)
      m.rotation.x = -Math.PI / 2
      m.rotation.z = rand(0, TAU)
      m.position.set(Math.cos(a) * r, 0.005 + i * 0.0002, Math.sin(a) * r)
      this.scene.add(m)
    }

    // center ring mark
    const ring = new THREE.Mesh(
      new THREE.RingGeometry(6.4, 6.65, 64),
      new THREE.MeshStandardMaterial({ color: 0x3d2c1d, roughness: 0.95, transparent: true, opacity: 0.65 })
    )
    ring.rotation.x = -Math.PI / 2
    ring.position.y = 0.008
    this.scene.add(ring)

    // faint center emblem
    const em = new THREE.Mesh(
      new THREE.CircleGeometry(1.6, 32),
      new THREE.MeshStandardMaterial({ map: emblemTexture(), transparent: true, opacity: 0.18, color: 0x2a1a10, roughness: 1, depthWrite: false })
    )
    em.rotation.x = -Math.PI / 2
    em.position.y = 0.009
    this.scene.add(em)
  }

  buildStands() {
    const stone = stoneTexture(this.renderer)
    const stoneMat = new THREE.MeshStandardMaterial({ map: stone, color: 0x8a7d70, roughness: 1 })
    const darkStone = new THREE.MeshStandardMaterial({ map: stone, color: 0x3e3631, roughness: 1 })

    // inner wall ring
    const segs = 44
    const wallGeo = new THREE.BoxGeometry(3.9, 1.75, 1.15)
    const walls = new THREE.InstancedMesh(wallGeo, stoneMat, segs)
    walls.castShadow = !this.low
    walls.receiveShadow = true
    const m = new THREE.Matrix4()
    const q = new THREE.Quaternion()
    const p = new THREE.Vector3()
    const s = new THREE.Vector3(1, 1, 1)
    for (let i = 0; i < segs; i++) {
      const a = (i / segs) * TAU
      p.set(Math.cos(a) * (ARENA_RADIUS + 1.2), 0.87, Math.sin(a) * (ARENA_RADIUS + 1.2))
      q.setFromAxisAngle(new THREE.Vector3(0, 1, 0), -a + Math.PI / 2)
      m.compose(p, q, s)
      walls.setMatrixAt(i, m)
    }
    this.scene.add(walls)

    // wall cap
    const cap = new THREE.Mesh(
      new THREE.TorusGeometry(ARENA_RADIUS + 1.2, 0.22, 6, 96),
      darkStone
    )
    cap.rotation.x = Math.PI / 2
    cap.position.y = 1.78
    this.scene.add(cap)

    // tiered stands
    const tiers = [
      { r0: 25.4, r1: 28.6, y: 1.6 },
      { r0: 28.2, r1: 31.6, y: 3.0 },
      { r0: 31.2, r1: 35.0, y: 4.4 }
    ]
    for (const t of tiers) {
      const ring = new THREE.Mesh(new THREE.RingGeometry(t.r0, t.r1, 80, 1), stoneMat)
      ring.rotation.x = -Math.PI / 2
      ring.position.y = t.y
      ring.receiveShadow = true
      this.scene.add(ring)
      const riser = new THREE.Mesh(
        new THREE.CylinderGeometry(t.r1, t.r1, 1.5, 80, 1, true),
        darkStone
      )
      riser.position.y = t.y - 0.75
      riser.material.side = THREE.DoubleSide
      this.scene.add(riser)
    }

    // outer wall
    const outerWall = new THREE.Mesh(
      new THREE.CylinderGeometry(37.5, 37.5, 16, 64, 1, true),
      darkStone
    )
    outerWall.position.y = 7
    outerWall.material.side = THREE.BackSide
    this.scene.add(outerWall)

    // decorative arches / alcoves silhouetted against the stands
    for (let i = 0; i < 14; i++) {
      const a = (i / 14) * TAU + 0.05
      const arch = new THREE.Mesh(
        new THREE.BoxGeometry(2.4, 3.4, 0.4),
        new THREE.MeshStandardMaterial({ color: 0x120c0b, roughness: 1 })
      )
      arch.position.set(Math.cos(a) * 30, 4.4, Math.sin(a) * 30)
      arch.rotation.y = -a
      this.scene.add(arch)
    }
  }

  buildCrowd() {
    const count = this.low ? 150 : 330
    const bodyGeo = new THREE.CylinderGeometry(0.19, 0.26, 0.78, 5)
    const headGeo = new THREE.SphereGeometry(0.15, 6, 5)
    const mats = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 1, vertexColors: false })
    const bodyMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 1 })
    const headMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 1 })
    const bodies = new THREE.InstancedMesh(bodyGeo, bodyMat, count)
    const heads = new THREE.InstancedMesh(headGeo, headMat, count)
    bodies.instanceMatrix.setUsage(THREE.DynamicDrawUsage)
    heads.instanceMatrix.setUsage(THREE.DynamicDrawUsage)

    const palette = [
      0x2b1914, 0x3a2318, 0x1c1512, 0x44251a, 0x2a2220, 0x33201c, 0x4a2a1c,
      0x241a16, 0x3d2a20, 0x2d2024, 0x51301e, 0x36241b
    ]
    const skin = [0x9a6b4e, 0x7c5138, 0xb08060, 0x6a4430, 0x8a5d42]
    const c = new THREE.Color()
    for (let i = 0; i < count; i++) {
      const tier = randInt(0, 2)
      const rad = [26.4, 29.6, 32.8][tier] + rand(-0.8, 0.8)
      const y = [1.66, 3.06, 4.46][tier] + 0.42
      const a = rand(0, TAU)
      const x = Math.cos(a) * rad, z = Math.sin(a) * rad
      bodies.setColorAt(i, c.setHex(palette[randInt(0, palette.length - 1)]))
      heads.setColorAt(i, c.setHex(skin[randInt(0, skin.length - 1)]))
      this.crowdBase.push({ x, y, z, a, phase: rand(0, TAU), speed: rand(0.7, 1.6), scale: rand(0.85, 1.15) })
    }
    this.crowd = bodies
    this.crowdHeads = heads
    bodies.instanceColor.needsUpdate = true
    heads.instanceColor.needsUpdate = true
    bodies.frustumCulled = false
    heads.frustumCulled = false
    this.scene.add(bodies, heads)
    this.updateCrowd(0)
  }

  updateCrowd(t) {
    if (!this.crowd) return
    const m = this._tmpM
    const q = this._tmpQ
    const e = this._tmpE
    const p = this._tmpV
    const s = this._tmpS
    const energy = this.crowdEnergy
    for (let i = 0; i < this.crowdBase.length; i++) {
      const b = this.crowdBase[i]
      const bob = Math.sin(t * b.speed + b.phase) * (0.025 + energy * 0.11)
      const sway = Math.sin(t * 0.7 + b.phase * 2) * (0.02 + energy * 0.08)
      e.set(0, -b.a + Math.PI / 2 + sway, 0)
      q.setFromEuler(e)
      p.set(b.x, b.y + bob, b.z)
      s.set(b.scale, b.scale, b.scale)
      m.compose(p, q, s)
      this.crowd.setMatrixAt(i, m)
      p.y = b.y + 0.55 * b.scale + bob
      m.compose(p, q, s)
      this.crowdHeads.setMatrixAt(i, m)
    }
    this.crowd.instanceMatrix.needsUpdate = true
    this.crowdHeads.instanceMatrix.needsUpdate = true
  }

  buildPillars() {
    const stone = stoneTexture(this.renderer)
    const mat = new THREE.MeshStandardMaterial({ map: stone, color: 0x6b6058, roughness: 1 })
    const dark = new THREE.MeshStandardMaterial({ color: 0x1d1714, roughness: 1 })
    const flameTex = flameTexture()
    const torchPositions = []

    for (let i = 0; i < 10; i++) {
      const a = (i / 10) * TAU + 0.31
      const r = ARENA_RADIUS + 2.3
      const x = Math.cos(a) * r, z = Math.sin(a) * r
      const g = new THREE.Group()
      g.position.set(x, 0, z)
      const base = makeMesh(new THREE.CylinderGeometry(0.62, 0.78, 0.5, 10), dark, [0, 0.25, 0])
      const shaft = makeMesh(new THREE.CylinderGeometry(0.36, 0.46, 5.4, 10), mat, [0, 3.05, 0])
      shaft.castShadow = !this.low
      const cap = makeMesh(new THREE.CylinderGeometry(0.55, 0.42, 0.35, 10), dark, [0, 5.9, 0])
      g.add(base, shaft, cap)
      // brazier
      const bowl = makeMesh(new THREE.CylinderGeometry(0.62, 0.36, 0.42, 10), dark, [0, 6.25, 0])
      g.add(bowl)
      // emblem on shaft
      const em = new THREE.Mesh(
        new THREE.CircleGeometry(0.28, 16),
        new THREE.MeshStandardMaterial({ map: emblemTexture(), transparent: true, color: 0xb09a72, roughness: 1, opacity: 0.8 })
      )
      em.position.set(0, 3.4, 0.47)
      g.add(em)
      this.scene.add(g)

      // flame
      const flame = new THREE.Sprite(new THREE.SpriteMaterial({
        map: flameTex, color: 0xffb05a, transparent: true, blending: THREE.AdditiveBlending,
        depthWrite: false, opacity: 0.95, fog: false
      }))
      flame.position.set(0, 6.9, 0)
      flame.scale.set(1.5, 2.2, 1)
      g.add(flame)
      this.flames.push({ sprite: flame, phase: rand(0, TAU), base: 1, torch: g })

      if (i % 2 === 0) {
        const light = new THREE.PointLight(0xff7a35, 26, 17, 2)
        light.position.set(0, 6.7, 0)
        g.add(light)
        torchPositions.push({ light, phase: rand(0, TAU) })
      }
      this.embers.push({ ...this.emberData(x, z, 6.8) })
    }
    this.torchLights = torchPositions

    // embers (points)
    const count = 90
    const pos = new Float32Array(count * 3)
    const col = new Float32Array(count * 3)
    this.emberSeeds = []
    for (let i = 0; i < count; i++) {
      const s = this.embers[i % this.embers.length]
      pos[i * 3] = s.x; pos[i * 3 + 1] = s.y; pos[i * 3 + 2] = s.z
      col[i * 3] = 1; col[i * 3 + 1] = rand(0.35, 0.65); col[i * 3 + 2] = 0.12
      this.emberSeeds.push({ ...s, speed: rand(0.4, 1.4), phase: rand(0, TAU), amp: rand(0.2, 0.9) })
    }
    const geo = new THREE.BufferGeometry()
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3))
    geo.setAttribute('color', new THREE.BufferAttribute(col, 3))
    const pmat = new THREE.PointsMaterial({
      size: 0.09, vertexColors: true, transparent: true, opacity: 0.9,
      blending: THREE.AdditiveBlending, depthWrite: false, sizeAttenuation: true
    })
    this.emberPoints = new THREE.Points(geo, pmat)
    this.emberPoints.frustumCulled = false
    this.scene.add(this.emberPoints)
  }

  emberData(x, z, y) {
    return { x: x + rand(-0.15, 0.15), y, z: z + rand(-0.15, 0.15) }
  }

  buildGates() {
    const dark = new THREE.MeshStandardMaterial({ color: 0x16100e, roughness: 0.95 })
    const iron = new THREE.MeshStandardMaterial({ color: 0x3d3a37, roughness: 0.55, metalness: 0.7 })
    const stone = new THREE.MeshStandardMaterial({ color: 0x2a2420, roughness: 1 })

    for (let i = 0; i < 4; i++) {
      const a = (i / 4) * TAU + Math.PI / 4
      const r = ARENA_RADIUS + 0.4
      const x = Math.cos(a) * r, z = Math.sin(a) * r
      const g = new THREE.Group()
      g.position.set(x, 0, z)
      g.lookAt(0, 0, 0)
      // gate opening (dark)
      const hole = new THREE.Mesh(new THREE.PlaneGeometry(2.7, 3.5), dark)
      hole.position.set(0, 1.78, -0.62)
      g.add(hole)
      // arch
      const arch = new THREE.Mesh(new THREE.TorusGeometry(1.55, 0.3, 6, 16, Math.PI), stone)
      arch.position.set(0, 3.45, -0.7)
      g.add(arch)
      // posts
      for (const sx of [-1, 1]) {
        const post = makeMesh(new THREE.CylinderGeometry(0.3, 0.36, 3.5, 6), stone, [sx * 1.5, 1.75, -0.7])
        g.add(post)
      }
      // portcullis bars
      const bars = new THREE.Group()
      for (let b = -2; b <= 2; b++) {
        const bar = makeMesh(new THREE.CylinderGeometry(0.045, 0.045, 3.1, 5), iron, [b * 0.52, 1.6, -0.35])
        bars.add(bar)
      }
      for (let b = 0; b < 4; b++) {
        const bar = makeMesh(new THREE.BoxGeometry(2.5, 0.07, 0.07), iron, [0, 0.55 + b * 0.72, -0.35])
        bars.add(bar)
      }
      g.add(bars)
      this.scene.add(g)

      // spawn just inside the gate
      const sr = ARENA_RADIUS - 1.2
      this.spawnPoints.push(new THREE.Vector3(Math.cos(a) * sr, 0, Math.sin(a) * sr))

      // gate torches
      for (const sx of [-1, 1]) {
        const pole = makeMesh(new THREE.CylinderGeometry(0.05, 0.05, 1.4, 5), iron, [sx * 1.9, 2.0, -0.4])
        g.add(pole)
        const flame = new THREE.Sprite(new THREE.SpriteMaterial({
          map: flameTexture(), color: 0xff8a3a, transparent: true, blending: THREE.AdditiveBlending,
          depthWrite: false, fog: false
        }))
        flame.position.set(sx * 1.9, 2.85, -0.4)
        flame.scale.set(0.65, 1.0, 1)
        g.add(flame)
        this.flames.push({ sprite: flame, phase: rand(0, TAU), base: 0.65 })
      }
    }
  }

  buildProps() {
    const bone = new THREE.MeshStandardMaterial({ color: 0xcfc2a8, roughness: 0.85 })
    const darkBone = new THREE.MeshStandardMaterial({ color: 0x9c8f78, roughness: 0.9 })
    const iron = new THREE.MeshStandardMaterial({ color: 0x2f2c29, roughness: 0.5, metalness: 0.6 })

    // skulls on spikes around the wall
    for (let i = 0; i < 14; i++) {
      const a = rand(0, TAU)
      const r = ARENA_RADIUS + 0.1
      const g = new THREE.Group()
      g.position.set(Math.cos(a) * r, 0, Math.sin(a) * r)
      const spike = makeMesh(new THREE.CylinderGeometry(0.035, 0.07, 1.2, 5), iron, [0, 1.55, 0])
      const skull = new THREE.Mesh(new THREE.SphereGeometry(0.17, 8, 6), bone)
      skull.scale.set(1, 0.95, 1.15)
      skull.position.y = 2.1
      skull.castShadow = !this.low
      const jaw = makeMesh(new THREE.BoxGeometry(0.18, 0.09, 0.2), darkBone, [0, 1.97, 0.06])
      g.add(spike, skull, jaw)
      this.scene.add(g)
    }

    // scattered bones near the edges
    for (let i = 0; i < 26; i++) {
      const a = rand(0, TAU), r = rand(ARENA_RADIUS - 4.5, ARENA_RADIUS - 0.4)
      const b = new THREE.Mesh(new THREE.CapsuleGeometry(0.035, rand(0.16, 0.4), 3, 5), chance(0.5) ? bone : darkBone)
      b.position.set(Math.cos(a) * r, 0.05, Math.sin(a) * r)
      b.rotation.set(Math.PI / 2 + rand(-0.3, 0.3), rand(0, TAU), rand(-0.3, 0.3))
      b.receiveShadow = true
      this.scene.add(b)
    }

    // banners between pillars
    const btex = bannerTexture()
    for (let i = 0; i < 8; i++) {
      const a = (i / 8) * TAU + 0.6
      const r = ARENA_RADIUS + 1.05
      const banner = new THREE.Mesh(
        new THREE.PlaneGeometry(1.7, 3.7, 1, 4),
        new THREE.MeshStandardMaterial({ map: btex, side: THREE.DoubleSide, roughness: 0.95, color: 0xb08a7a })
      )
      banner.position.set(Math.cos(a) * r, 4.2, Math.sin(a) * r)
      banner.rotation.y = -a + Math.PI / 2
      this.scene.add(banner)
      this.banners.push({ mesh: banner, phase: rand(0, TAU), baseRot: banner.rotation.y })
    }

    // torches on wall
    const flameTex = flameTexture()
    for (let i = 0; i < 12; i++) {
      const a = (i / 12) * TAU + 0.14
      const r = ARENA_RADIUS + 0.35
      const g = new THREE.Group()
      g.position.set(Math.cos(a) * r, 2.1, Math.sin(a) * r)
      g.rotation.y = -a + Math.PI
      const bracket = makeMesh(new THREE.BoxGeometry(0.08, 0.08, 0.55), iron, [0, 0, 0.25])
      const cup = makeMesh(new THREE.CylinderGeometry(0.16, 0.1, 0.22, 8), iron, [0, 0.08, 0.5])
      const fl = new THREE.Sprite(new THREE.SpriteMaterial({
        map: flameTex, color: 0xff8f42, transparent: true, blending: THREE.AdditiveBlending,
        depthWrite: false, fog: false
      }))
      fl.position.set(0, 0.5, 0.5)
      fl.scale.set(0.8, 1.25, 1)
      g.add(bracket, cup, fl)
      this.scene.add(g)
      this.flames.push({ sprite: fl, phase: rand(0, TAU), base: 0.8 })
    }
  }

  buildLights() {
    const hemi = new THREE.HemisphereLight(0x4a2b33, 0x1d130c, 0.9)
    this.scene.add(hemi)

    const moon = new THREE.DirectionalLight(0x9fb2d6, 2.4)
    moon.position.set(-22, 32, -18)
    moon.castShadow = !this.low
    if (!this.low) {
      moon.shadow.mapSize.set(2048, 2048)
      moon.shadow.camera.left = -30
      moon.shadow.camera.right = 30
      moon.shadow.camera.top = 30
      moon.shadow.camera.bottom = -30
      moon.shadow.camera.near = 1
      moon.shadow.camera.far = 90
      moon.shadow.bias = -0.0006
      moon.shadow.normalBias = 0.02
    }
    this.scene.add(moon)
    this.moon = moon

    const fill = new THREE.DirectionalLight(0x7a2830, 0.7)
    fill.position.set(18, 8, 22)
    this.scene.add(fill)

    // central warm light from braziers (cheap ambient boost)
    const center = new THREE.PointLight(0xff7430, 22, 40, 2)
    center.position.set(0, 9, 0)
    this.scene.add(center)
    this.centerLight = center
  }

  buildDust() {
    const count = this.low ? 90 : 220
    const pos = new Float32Array(count * 3)
    this.dustSeeds = []
    for (let i = 0; i < count; i++) {
      const a = rand(0, TAU), r = rand(0, ARENA_RADIUS - 1)
      const p = { x: Math.cos(a) * r, y: rand(0.2, 5.5), z: Math.sin(a) * r, phase: rand(0, TAU), speed: rand(0.1, 0.4) }
      this.dustSeeds.push(p)
      pos[i * 3] = p.x; pos[i * 3 + 1] = p.y; pos[i * 3 + 2] = p.z
    }
    const geo = new THREE.BufferGeometry()
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3))
    this.dust = new THREE.Points(geo, new THREE.PointsMaterial({
      size: 0.045, color: 0xd8c2a0, transparent: true, opacity: 0.28,
      depthWrite: false, sizeAttenuation: true
    }))
    this.dust.frustumCulled = false
    this.scene.add(this.dust)
  }

  excite(amount = 1) {
    this.crowdEnergy = clamp(this.crowdEnergy + amount * 0.35, 0, 1)
    this.crowdEnergyTimer = 2.2
  }

  update(dt, t) {
    this.time = t
    // flames
    for (const f of this.flames) {
      const n = Math.sin(t * 13 + f.phase) * 0.5 + Math.sin(t * 23 + f.phase * 2) * 0.3
      const s = 0.85 + n * 0.22
      f.sprite.scale.set(f.base * s, f.base * 1.55 * (1 + n * 0.16), 1)
      f.sprite.material.opacity = 0.78 + n * 0.18
    }
    // torch light flicker
    for (const l of this.torchLights) {
      l.light.intensity = 22 + Math.sin(t * 9 + l.phase) * 4 + Math.sin(t * 17 + l.phase * 3) * 2
    }
    if (this.centerLight) this.centerLight.intensity = 20 + Math.sin(t * 5.1) * 2

    // banners sway
    for (const b of this.banners) {
      b.mesh.rotation.y = b.baseRot + Math.sin(t * 0.9 + b.phase) * 0.06
      b.mesh.rotation.x = Math.sin(t * 1.3 + b.phase) * 0.02
    }

    // crowd
    this.crowdEnergy = Math.max(0, this.crowdEnergy - dt * 0.22)
    this.updateCrowd(t)

    // embers
    if (this.emberPoints) {
      const attr = this.emberPoints.geometry.attributes.position
      for (let i = 0; i < this.emberSeeds.length; i++) {
        const e = this.emberSeeds[i]
        const yy = 6.8 + ((t * e.speed + e.phase) % 3.4)
        attr.array[i * 3] = e.x + Math.sin(t * e.speed * 2 + e.phase) * e.amp * 0.5
        attr.array[i * 3 + 1] = yy
        attr.array[i * 3 + 2] = e.z + Math.cos(t * e.speed * 1.7 + e.phase) * e.amp * 0.5
      }
      attr.needsUpdate = true
    }

    // dust
    if (this.dust) {
      const attr = this.dust.geometry.attributes.position
      for (let i = 0; i < this.dustSeeds.length; i++) {
        const p = this.dustSeeds[i]
        attr.array[i * 3] = p.x + Math.sin(t * p.speed + p.phase) * 1.4
        attr.array[i * 3 + 1] = p.y + Math.sin(t * p.speed * 0.7 + p.phase) * 0.7
        attr.array[i * 3 + 2] = p.z + Math.cos(t * p.speed + p.phase) * 1.4
      }
      attr.needsUpdate = true
    }
  }
}

import * as THREE from 'three'
import { rand, randInt, chance, clamp, TAU, bloodSplatTexture, softDropTexture, makeCanvas } from './utils.js'
import { sound } from './audio.js'

const GRAVITY = -22

/* ------------------------------------------------------------------ */
/* Blood droplets                                                      */
/* ------------------------------------------------------------------ */

export class BloodParticles {
  constructor(scene, renderer, count = 1400) {
    this.scene = scene
    this.max = count
    this.cursor = 0
    this.particles = []

    const geo = new THREE.BufferGeometry()
    this.pos = new Float32Array(count * 3)
    this.col = new Float32Array(count * 3)
    this.size = new Float32Array(count)
    this.alpha = new Float32Array(count)
    this.vel = new Float32Array(count * 3)
    this.life = new Float32Array(count)
    this.maxLife = new Float32Array(count)
    this.grounded = new Uint8Array(count)
    this.grav = new Float32Array(count)

    for (let i = 0; i < count; i++) {
      this.pos[i * 3 + 1] = -999
      this.alpha[i] = 0
      this.particles.push({ active: false, x: 0, y: 0, z: 0, vx: 0, vy: 0, vz: 0, life: 0, max: 1, size: 0.05, r: 0.4, g: 0.02, b: 0.03, ground: false, grav: 1 })
    }

    geo.setAttribute('position', new THREE.BufferAttribute(this.pos, 3))
    geo.setAttribute('aColor', new THREE.BufferAttribute(this.col, 3))
    geo.setAttribute('aSize', new THREE.BufferAttribute(this.size, 1))
    geo.setAttribute('aAlpha', new THREE.BufferAttribute(this.alpha, 1))
    geo.setDrawRange(0, count)
    geo.boundingSphere = new THREE.Sphere(new THREE.Vector3(), 100)

    const map = softDropTexture()
    this.material = new THREE.ShaderMaterial({
      transparent: true,
      depthWrite: false,
      uniforms: {
        uMap: { value: map },
        uScale: { value: 500 }
      },
      vertexShader: /* glsl */`
        attribute vec3 aColor;
        attribute float aSize;
        attribute float aAlpha;
        varying vec3 vColor;
        varying float vAlpha;
        uniform float uScale;
        void main() {
          vColor = aColor;
          vAlpha = aAlpha;
          vec4 mv = modelViewMatrix * vec4(position, 1.0);
          gl_PointSize = aSize * (uScale / max(0.35, -mv.z));
          gl_Position = projectionMatrix * mv;
        }
      `,
      fragmentShader: /* glsl */`
        uniform sampler2D uMap;
        varying vec3 vColor;
        varying float vAlpha;
        void main() {
          if (vAlpha <= 0.001) discard;
          vec4 t = texture2D(uMap, gl_PointCoord);
          float a = t.a * vAlpha;
          if (a < 0.01) discard;
          gl_FragColor = vec4(vColor, a);
        }
      `
    })
    this.setSize(renderer)
    this.points = new THREE.Points(geo, this.material)
    this.points.frustumCulled = false
    this.points.renderOrder = 3
    scene.add(this.points)
    this.geo = geo
  }

  setSize(renderer) {
    const h = renderer.domElement.height || 900
    this.material.uniforms.uScale.value = h * 0.55
  }

  spawn(x, y, z, opts = {}) {
    const p = this.particles[this.cursor]
    this.cursor = (this.cursor + 1) % this.max
    const spread = opts.spread ?? 0.2
    p.active = true
    p.x = x + rand(-spread, spread)
    p.y = y + rand(-spread, spread)
    p.z = z + rand(-spread, spread)
    p.vx = (opts.vx ?? 0) + rand(-1, 1) * (opts.chaos ?? 1.6)
    p.vy = (opts.vy ?? 0) + rand(-0.4, 1.1) * (opts.chaos ?? 1.6)
    p.vz = (opts.vz ?? 0) + rand(-1, 1) * (opts.chaos ?? 1.6)
    p.life = 0
    p.max = rand(0.5, 1.5) * (opts.life ?? 1)
    p.size = rand(0.035, 0.12) * (opts.size ?? 1)
    const tone = rand(0.55, 1)
    p.r = 0.38 * tone
    p.g = 0.012 + rand(0, 0.02)
    p.b = 0.02 + rand(0, 0.02)
    p.ground = false
    p.grav = opts.gravity ?? 1
    return p
  }

  burst(pos, opts = {}) {
    const n = opts.count ?? 18
    for (let i = 0; i < n; i++) this.spawn(pos.x, pos.y, pos.z, opts)
  }

  sprayCone(pos, dir, opts = {}) {
    const n = opts.count ?? 20
    const speed = opts.speed ?? 4
    const spread = opts.spread ?? 0.55
    for (let i = 0; i < n; i++) {
      const p = this.spawn(pos.x, pos.y, pos.z, { ...opts, chaos: 0 })
      const vx = dir.x * speed + rand(-1, 1) * spread * speed
      const vy = dir.y * speed + rand(-0.4, 1.2) * spread * speed
      const vz = dir.z * speed + rand(-1, 1) * spread * speed
      p.vx = vx; p.vy = vy; p.vz = vz
    }
  }

  update(dt, decals) {
    const posA = this.pos
    const colA = this.col
    const sizeA = this.size
    const alphaA = this.alpha
    for (let i = 0; i < this.max; i++) {
      const p = this.particles[i]
      if (!p.active) { alphaA[i] = 0; continue }
      p.life += dt
      if (p.life >= p.max) {
        p.active = false
        alphaA[i] = 0
        posA[i * 3 + 1] = -999
        continue
      }
      p.vy += GRAVITY * p.grav * dt
      p.x += p.vx * dt
      p.y += p.vy * dt
      p.z += p.vz * dt
      if (p.y <= 0.015) {
        if (!p.ground) {
          p.ground = true
          if (decals && chance(0.22)) decals.add(p.x, 0.011, p.z, rand(0.1, 0.35), rand(0, TAU))
        }
        p.active = false
        alphaA[i] = 0
        posA[i * 3 + 1] = -999
        continue
      }
      posA[i * 3] = p.x
      posA[i * 3 + 1] = p.y
      posA[i * 3 + 2] = p.z
      colA[i * 3] = p.r
      colA[i * 3 + 1] = p.g
      colA[i * 3 + 2] = p.b
      sizeA[i] = p.size
      const t = p.life / p.max
      alphaA[i] = Math.min(1, (1 - t) * 2.2) * 0.95
    }
    this.geo.attributes.position.needsUpdate = true
    this.geo.attributes.aColor.needsUpdate = true
    this.geo.attributes.aSize.needsUpdate = true
    this.geo.attributes.aAlpha.needsUpdate = true
  }

  clear() {
    for (const p of this.particles) p.active = false
    this.alpha.fill(0)
    this.pos.fill(-999)
    this.geo.attributes.position.needsUpdate = true
    this.geo.attributes.aAlpha.needsUpdate = true
  }
}

/* ------------------------------------------------------------------ */
/* Ground decals & pools                                               */
/* ------------------------------------------------------------------ */

export class BloodDecals {
  constructor(scene, max = 460) {
    this.max = max
    this.cursor = 0
    const geo = new THREE.PlaneGeometry(1, 1)
    geo.rotateX(-Math.PI / 2)
    const mat = new THREE.MeshBasicMaterial({
      map: bloodSplatTexture(), transparent: true, depthWrite: false,
      polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -2,
      color: 0xffffff, opacity: 0.94
    })
    this.mesh = new THREE.InstancedMesh(geo, mat, max)
    this.mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage)
    this.mesh.renderOrder = 1
    this.mesh.frustumCulled = false
    this.mesh.count = 0
    this.count = 0
    this.matrix = new THREE.Matrix4()
    this.quat = new THREE.Quaternion()
    this.pos = new THREE.Vector3()
    this.scale = new THREE.Vector3()
    const c = new THREE.Color()
    for (let i = 0; i < max; i++) {
      this.mesh.setColorAt(i, c.setRGB(1, 1, 1))
      this.matrix.makeScale(0, 0, 0)
      this.mesh.setMatrixAt(i, this.matrix)
    }
    scene.add(this.mesh)
  }

  add(x, z, scale = 1, rot = 0, tint = 1) {
    const i = this.cursor
    this.cursor = (this.cursor + 1) % this.max
    this.count = Math.min(this.count + 1, this.max)
    this.mesh.count = this.count
    this.pos.set(x, 0.012 + (i % 9) * 0.00035, z)
    this.quat.setFromAxisAngle(new THREE.Vector3(0, 1, 0), rot)
    this.scale.set(scale * rand(0.9, 1.15), 1, scale * rand(0.9, 1.15))
    this.matrix.compose(this.pos, this.quat, this.scale)
    this.mesh.setMatrixAt(i, this.matrix)
    const c = new THREE.Color().setRGB(0.85 * tint, 0.75 * tint, 0.75 * tint)
    this.mesh.setColorAt(i, c)
    this.mesh.instanceMatrix.needsUpdate = true
    if (this.mesh.instanceColor) this.mesh.instanceColor.needsUpdate = true
  }

  clear() {
    this.matrix.makeScale(0, 0, 0)
    for (let i = 0; i < this.max; i++) this.mesh.setMatrixAt(i, this.matrix)
    this.mesh.count = 0
    this.cursor = 0
    this.count = 0
    this.mesh.instanceMatrix.needsUpdate = true
  }
}

export class BloodPools {
  constructor(scene, max = 26) {
    this.scene = scene
    this.max = max
    this.list = []
    const tex = this.poolTexture()
    this.mat = new THREE.MeshBasicMaterial({
      map: tex, transparent: true, depthWrite: false, opacity: 0.92,
      color: 0x5c050b, polygonOffset: true, polygonOffsetFactor: -3, polygonOffsetUnits: -3
    })
    this.geo = new THREE.CircleGeometry(1, 24)
    this.geo.rotateX(-Math.PI / 2)
  }

  poolTexture() {
    const s = 128
    const c = makeCanvas(s, s)
    const ctx = c.getContext('2d')
    const g = ctx.createRadialGradient(s / 2, s / 2, 4, s / 2, s / 2, s / 2)
    g.addColorStop(0, 'rgba(40,0,3,0.98)')
    g.addColorStop(0.55, 'rgba(70,2,7,0.9)')
    g.addColorStop(0.82, 'rgba(80,3,8,0.55)')
    g.addColorStop(1, 'rgba(60,0,4,0)')
    ctx.fillStyle = g
    ctx.beginPath(); ctx.arc(s / 2, s / 2, s / 2, 0, TAU); ctx.fill()
    // irregular edge blobs
    for (let i = 0; i < 40; i++) {
      const a = rand(0, TAU), d = rand(34, 60)
      ctx.fillStyle = `rgba(60,1,6,${rand(0.2, 0.6)})`
      ctx.beginPath(); ctx.ellipse(s / 2 + Math.cos(a) * d, s / 2 + Math.sin(a) * d, rand(2, 8), rand(2, 7), a, 0, TAU); ctx.fill()
    }
    const t = new THREE.CanvasTexture(c)
    t.colorSpace = THREE.SRGBColorSpace
    return t
  }

  add(x, z, target = 1.4) {
    let pool = this.list.find((p) => p.life === 0)
    if (!pool) {
      if (this.list.length < this.max) {
        const mesh = new THREE.Mesh(this.geo, this.mat)
        mesh.renderOrder = 2
        mesh.rotation.y = rand(0, TAU)
        this.scene.add(mesh)
        pool = { mesh, size: 0.01, target: 1, life: 1, growing: true }
        this.list.push(pool)
      } else {
        pool = this.list[0]
        this.list.push(this.list.shift())
      }
    }
    pool.mesh.position.set(x, 0.014 + this.list.indexOf(pool) * 0.0002, z)
    pool.mesh.rotation.y = rand(0, TAU)
    pool.target = target * rand(0.8, 1.3)
    pool.size = Math.max(0.25, pool.size * 0.6)
    pool.life = 1
    pool.growing = true
    pool.mesh.visible = true
    return pool
  }

  update(dt) {
    for (const p of this.list) {
      if (!p.mesh.visible) continue
      if (p.growing) {
        p.size += (p.target - p.size) * Math.min(1, dt * 1.5)
        if (Math.abs(p.target - p.size) < 0.02) p.growing = false
      } else {
        p.life -= dt * 0.012
        p.size += dt * 0.02
      }
      p.mesh.scale.set(p.size, 1, p.size)
      p.mesh.material.opacity = 1
    }
  }

  clear() {
    for (const p of this.list) p.mesh.visible = false
    this.list = []
  }
}

/* ------------------------------------------------------------------ */
/* Physical debris (severed limbs, weapons, skulls, guts)              */
/* ------------------------------------------------------------------ */

export class Debris {
  constructor(scene, blood, decals, pools) {
    this.scene = scene
    this.blood = blood
    this.decals = decals
    this.pools = pools
    this.items = []
    this.max = 54
    this.tmp = new THREE.Vector3()
  }

  add(object, vel, angVel, radius = 0.25, opts = {}) {
    object.updateWorldMatrix(true, true)
    if (object.parent !== this.scene) this.scene.attach(object)
    const item = {
      object,
      vx: vel.x, vy: vel.y, vz: vel.z,
      ax: angVel.x, ay: angVel.y, az: angVel.z,
      radius,
      restY: opts.restY ?? radius * 0.42,
      life: 0,
      settled: false,
      bleeds: opts.bleeds ?? 0,
      dripTimer: 0,
      bounce: opts.bounce ?? 0.28,
      friction: opts.friction ?? 0.88,
      onImpact: opts.onImpact || null,
      pool: false
    }
    this.items.push(item)
    if (this.items.length > this.max) {
      const old = this.items.shift()
      old.object.parent?.remove(old.object)
    }
    return item
  }

  update(dt) {
    for (const it of this.items) {
      if (it.settled) continue
      it.life += dt
      it.vy += GRAVITY * dt
      const o = it.object
      o.position.x += it.vx * dt
      o.position.y += it.vy * dt
      o.position.z += it.vz * dt
      o.rotation.x += it.ax * dt
      o.rotation.y += it.ay * dt
      o.rotation.z += it.az * dt

      // arena bounds
      const r = Math.hypot(o.position.x, o.position.z)
      const limit = 24.2
      if (r > limit) {
        const nx = o.position.x / r, nz = o.position.z / r
        o.position.x = nx * limit
        o.position.z = nz * limit
        it.vx *= -0.45
        it.vz *= -0.45
      }

      if (o.position.y < it.restY) {
        o.position.y = it.restY
        if (it.vy < -0.6) {
          const impact = Math.min(1, -it.vy / 8)
          if (it.bleeds) this.blood.burst(o.position, { count: Math.floor(4 + impact * 8), chaos: 1.5, size: 0.8, vy: 1 })
          if (!it.pool && it.bleeds && (impact > 0.22 || it.life > 1.2)) {
            this.pools.add(o.position.x, o.position.z, 0.5 + it.bleeds * 0.18)
            it.pool = true
          }
          if (impact > 0.5) sound.hitFlesh(0.35)
          it.vy = -it.vy * it.bounce
          it.ax *= 0.6; it.ay *= 0.7; it.az *= 0.6
          if (Math.abs(it.vy) < 0.6) it.vy = 0
        } else {
          it.vy = 0
        }
        it.vx *= Math.pow(it.friction, dt * 60)
        it.vz *= Math.pow(it.friction, dt * 60)
        it.ax *= Math.pow(0.2, dt)
        it.ay *= Math.pow(0.25, dt)
        it.az *= Math.pow(0.2, dt)
        if (Math.abs(it.vx) + Math.abs(it.vz) + Math.abs(it.ax) + Math.abs(it.az) < 0.02) {
          it.settled = true
          it.vx = it.vy = it.vz = 0
          it.ax = it.ay = it.az = 0
          if (it.bleeds && !it.pool) {
            this.pools.add(o.position.x, o.position.z, 0.6 + it.bleeds * 0.25)
            it.pool = true
          }
        }
      }

      // arterial drip while airborne
      if (it.bleeds > 0) {
        it.dripTimer -= dt
        if (it.dripTimer <= 0) {
          it.dripTimer = rand(0.03, 0.1)
          this.blood.spawn(o.position.x, o.position.y, o.position.z, {
            vy: rand(-0.4, 0.4), chaos: 0.5, size: 0.7, life: 1.2
          })
        }
      }
    }
  }

  clear() {
    for (const it of this.items) it.object.parent?.remove(it.object)
    this.items = []
  }
}

