  const brass = new THREE.MeshStandardMaterial({ color: 0x8a6a35, roughness: 0.45, metalness: 0.7 })
  const bloodMat = new THREE.MeshStandardMaterial({ color: 0x6b0810, roughness: 0.55 })

  if (kind === 'sword') {
    const grip = makeMesh(new THREE.CylinderGeometry(0.028, 0.032, 0.26, 6), wood, [0, -0.13, 0])
    const guard = makeMesh(new THREE.BoxGeometry(0.3, 0.045, 0.06), brass, [0, -0.27, 0])
    const blade = makeMesh(new THREE.BoxGeometry(0.075, 0.86, 0.022), steel, [0, -0.72, 0])
    const tip = makeMesh(new THREE.ConeGeometry(0.041, 0.16, 4), steel, [0, -1.22, 0])
    tip.rotation.y = Math.PI / 4
    const fuller = new THREE.Mesh(new THREE.BoxGeometry(0.016, 0.7, 0.026), darkSteel)
    fuller.position.set(0, -0.72, 0)
    g.add(grip, guard, blade, tip, fuller)
    const stain = new THREE.Mesh(new THREE.PlaneGeometry(0.05, 0.5), bloodMat)
    stain.position.set(0.038, -0.78, 0.012)
    stain.rotation.y = Math.PI / 2
    stain.visible = false
    g.userData.stain = stain
    g.add(stain)
    g.userData.length = 1.22
  } else if (kind === 'hammer') {
    const handle = makeMesh(new THREE.CylinderGeometry(0.035, 0.045, 0.95, 7), wood, [0, -0.48, 0])
    const head = makeMesh(new THREE.BoxGeometry(0.46, 0.3, 0.28), darkSteel, [0, -0.98, 0])
    const faceL = makeMesh(new THREE.BoxGeometry(0.1, 0.34, 0.32), steel, [-0.25, -0.98, 0])
    const faceR = makeMesh(new THREE.BoxGeometry(0.1, 0.34, 0.32), steel, [0.25, -0.98, 0])
    const band = makeMesh(new THREE.CylinderGeometry(0.052, 0.052, 0.1, 7), brass, [0, -0.83, 0])
    g.add(handle, head, faceL, faceR, band)
    const stain = new THREE.Mesh(new THREE.BoxGeometry(0.48, 0.1, 0.3), bloodMat)
    stain.position.set(0, -1.02, 0)
    stain.visible = false
    g.userData.stain = stain
    g.add(stain)
    g.userData.length = 1.06
  } else {
    // executioner axe
    const handle = makeMesh(new THREE.CylinderGeometry(0.04, 0.05, 1.05, 7), wood, [0, -0.52, 0])
    const head = makeMesh(new THREE.BoxGeometry(0.5, 0.28, 0.12), darkSteel, [0.16, -1.02, 0])
    const blade = makeMesh(new THREE.BoxGeometry(0.3, 0.5, 0.05), steel, [0.44, -1.02, 0])
    blade.rotation.z = 0.2
    const spike = makeMesh(new THREE.ConeGeometry(0.06, 0.24, 5), steel, [-0.2, -1.02, 0])
    spike.rotation.z = Math.PI / 2
    g.add(handle, head, blade, spike)
    const stain = new THREE.Mesh(new THREE.PlaneGeometry(0.3, 0.35), bloodMat)
    stain.position.set(0.46, -1.0, 0.03)
    stain.visible = false
    g.userData.stain = stain
    g.add(stain)
    g.userData.length = 1.2
  }
  g.scale.setScalar(scale)
  return g
}

export class Fighter {
  constructor(scene, gore, type, position, game) {
    this.scene = scene
    this.gore = gore
    this.game = game
    this.typeId = type
    this.type = ENEMY_TYPES[type]
    this.cfg = this.type
    this.scale = this.type.scale
    this.dead = false
    this.dying = false
    this.deathTimer = 0
    this.state = 'spawn'
    this.stateTime = 0
    this.attackCooldown = rand(0.5, 1.5)
    this.staggerTimer = 0
    this.blocking = false
    this.armGone = { l: false, r: false }
    this.legGone = { l: false, r: false }
    this.headGone = false
    this.struck = false
    this.walkPhase = rand(0, TAU)
    this.hitReact = 0
    this.hitReactDir = 0
    this.flash = 0
    this.bloodied = 0
    this.spawnPoint = position.clone()
    this.weaponKind = this.type.weapon
    this.partHp = {
      head: this.type.hp.head,
      torso: this.type.hp.torso,
      armL: this.type.hp.arm,
      armR: this.type.hp.arm,
      legL: this.type.hp.leg,
      legR: this.type.hp.leg
    }
    this.partMax = { ...this.partHp }
    this.hitParts = []
    this.severedParts = []
    this.attackTimer = 0
    this.attackIndex = 0
    this.moveSpeed = this.type.speed
    this.sideDir = chance(0.5) ? 1 : -1
    this.strafeTimer = rand(1, 2.4)
    this.facing = rand(0, TAU)
    this.wantBlock = chance(0.35)
    this.blockCooldown = rand(2, 5)
    this.wasHitByHeavy = false
    this.build()
    this.root.position.copy(position)
    this.root.rotation.y = this.facing
    scene.add(this.root)
    this.updateHitParts()
  }

  build() {
    const s = this.scale
    const skin = pick(SKIN)
    const leather = pick(LEATHER)
    const cloth = this.cfg.boss ? 0x1b1416 : pick(CLOTH)
    const skinMat = new THREE.MeshStandardMaterial({ color: skin, roughness: 0.72 })
    const leatherMat = new THREE.MeshStandardMaterial({ color: leather, roughness: 0.92 })
    const clothMat = new THREE.MeshStandardMaterial({ color: cloth, roughness: 0.95 })
    const ironMat = new THREE.MeshStandardMaterial({ color: this.cfg.boss ? 0x2b2b2f : 0x55575c, roughness: 0.4, metalness: 0.72 })
    const bronzeMat = new THREE.MeshStandardMaterial({ color: 0x8a6a3a, roughness: 0.38, metalness: 0.75 })
    const bloodMat = new THREE.MeshStandardMaterial({ color: 0x65080e, roughness: 0.5 })
    this.materials = { skinMat, leatherMat, clothMat, ironMat, bronzeMat, bloodMat }

    const root = new THREE.Group()
    root.name = 'fighter'
    this.root = root

    const hips = new THREE.Group()
    hips.position.y = 0.96
    root.add(hips)
    this.hips = hips

    const pelvis = makeMesh(new THREE.BoxGeometry(0.36, 0.26, 0.26), leatherMat, [0, 0, 0])
    hips.add(pelvis)
    this.pelvis = pelvis

    // skirt / loincloth
    const skirt = makeMesh(new THREE.CylinderGeometry(0.22, 0.3, 0.34, 8, 1, true), clothMat, [0, -0.1, 0])
    skirt.material = clothMat.clone()
    skirt.material.side = THREE.DoubleSide
    hips.add(skirt)

    const spine = new THREE.Group()
    spine.position.y = 0.13
    hips.add(spine)
    this.spine = spine

    const torso = makeMesh(new THREE.BoxGeometry(0.5, 0.48, 0.29), skinMat, [0, 0.26, 0])
    torso.geometry = this.taperBox(0.5, 0.42, 0.48, 0.3)
    spine.add(torso)
    this.torso = torso

    // chest armour
    if (this.cfg.boss) {
      const armor = makeMesh(new THREE.BoxGeometry(0.58, 0.4, 0.36), ironMat, [0, 0.3, 0.01])
      spine.add(armor)
      this.armorMesh = armor
      for (const sx of [-1, 1]) {
        const spike = makeMesh(new THREE.ConeGeometry(0.07, 0.28, 5), ironMat, [sx * 0.26, 0.52, 0])
        spine.add(spike)
      }
    } else if (this.typeId === 'duelist') {
      const strap = makeMesh(new THREE.BoxGeometry(0.56, 0.12, 0.33), leatherMat, [0, 0.32, 0])
      spine.add(strap)
      const belt = makeMesh(new THREE.BoxGeometry(0.54, 0.1, 0.34), bronzeMat, [0, 0.05, 0])
      spine.add(belt)
    } else {
      const strap = makeMesh(new THREE.BoxGeometry(0.34, 0.5, 0.34), leatherMat, [0, 0.28, 0])
      strap.rotation.y = 0.45
      spine.add(strap)
    }

    const neck = new THREE.Group()
    neck.position.set(0, 0.53, 0)
    spine.add(neck)
    this.neck = neck

    const head = new THREE.Mesh(new THREE.SphereGeometry(0.165, 12, 10), skinMat)
    head.scale.set(0.92, 1.08, 0.95)
    head.position.y = 0.15
    head.castShadow = true
    head.receiveShadow = true
    neck.add(head)
    this.head = head

    // face: eyes and mouth
    const eyeMat = new THREE.MeshBasicMaterial({ color: this.cfg.boss ? 0xff5a2a : 0x120909 })
    for (const sx of [-1, 1]) {
      const eye = new THREE.Mesh(new THREE.SphereGeometry(0.021, 5, 4), eyeMat)
      eye.position.set(sx * 0.058, 0.18, 0.148)
      neck.add(eye)
    }
    const mouth = new THREE.Mesh(new THREE.BoxGeometry(0.07, 0.012, 0.02), eyeMat)
    mouth.position.set(0, 0.08, 0.152)
    neck.add(mouth)

    if (this.typeId === 'duelist') {
      const helm = makeMesh(new THREE.CylinderGeometry(0.18, 0.19, 0.16, 10), bronzeMat, [0, 0.28, 0])
      const crest = makeMesh(new THREE.BoxGeometry(0.03, 0.14, 0.26), clothMat, [0, 0.39, 0])
      const guardN = makeMesh(new THREE.BoxGeometry(0.04, 0.12, 0.03), bronzeMat, [0, 0.17, 0.17])
      neck.add(helm, crest, guardN)
    } else if (this.cfg.boss) {
      const helm = makeMesh(new THREE.CylinderGeometry(0.2, 0.21, 0.24, 10), ironMat, [0, 0.28, 0])
      for (const sx of [-1, 1]) {
        const horn = makeMesh(new THREE.ConeGeometry(0.06, 0.42, 6), bronzeMat, [sx * 0.17, 0.38, 0])
        horn.rotation.z = sx * 0.65
        horn.rotation.x = -0.2
        neck.add(horn)
      }
      neck.add(helm)
    } else {
      const mask = makeMesh(new THREE.BoxGeometry(0.24, 0.2, 0.08), ironMat, [0, 0.16, 0.13])
      const strap = makeMesh(new THREE.BoxGeometry(0.35, 0.07, 0.35), leatherMat, [0, 0.2, 0])
      neck.add(mask, strap)
    }

    // arms
    const armGroups = {}
    for (const side of [-1, 1]) {
      const key = side < 0 ? 'l' : 'r'
      const shoulder = new THREE.Group()
      shoulder.position.set(side * 0.3, 0.47, 0)
      spine.add(shoulder)
      const upper = makeMesh(new THREE.CylinderGeometry(0.075, 0.062, 0.36, 7), skinMat, [0, -0.18, 0])
      shoulder.add(upper)
      if (this.cfg.boss) {
        const pauldron = makeMesh(new THREE.SphereGeometry(0.14, 7, 5), ironMat, [side * 0.03, 0.02, 0])
        pauldron.scale.set(1, 0.8, 1)
        shoulder.add(pauldron)
      }
      const elbow = new THREE.Group()
      elbow.position.y = -0.37
      shoulder.add(elbow)
      const fore = makeMesh(new THREE.CylinderGeometry(0.06, 0.05, 0.33, 7), skinMat, [0, -0.16, 0])
      elbow.add(fore)
      if (key === 'l') {
        // bracer
        const bracer = makeMesh(new THREE.CylinderGeometry(0.065, 0.06, 0.14, 7), leatherMat, [0, -0.26, 0])
        elbow.add(bracer)
      }
      const hand = new THREE.Group()
      hand.position.y = -0.34
      elbow.add(hand)
      const fist = makeMesh(new THREE.SphereGeometry(0.062, 7, 5), skinMat, [0, 0, 0])
      hand.add(fist)
      armGroups[key] = { shoulder, upper, elbow, fore, hand }
    }
    this.arms = armGroups

    // shoulders (visual)
    // legs
    const legGroups = {}
    for (const side of [-1, 1]) {
      const key = side < 0 ? 'l' : 'r'
      const thigh = new THREE.Group()
      thigh.position.set(side * 0.125, -0.06, 0)
      hips.add(thigh)
      const thighMesh = makeMesh(new THREE.CylinderGeometry(0.09, 0.075, 0.42, 7), skinMat, [0, -0.22, 0])
      thigh.add(thighMesh)
      const knee = new THREE.Group()
      knee.position.y = -0.44
      thigh.add(knee)
      const shin = makeMesh(new THREE.CylinderGeometry(0.072, 0.055, 0.4, 7), skinMat, [0, -0.2, 0])
      knee.add(shin)
      const shinGuard = makeMesh(new THREE.CylinderGeometry(0.083, 0.07, 0.2, 7), leatherMat, [0, -0.16, 0.01])
      knee.add(shinGuard)
      const foot = makeMesh(new THREE.BoxGeometry(0.13, 0.08, 0.24), leatherMat, [0, -0.41, 0.05])
      knee.add(foot)
      legGroups[key] = { thigh, thighMesh, knee, shin, foot }
    }
    this.legs = legGroups

    // weapon in right hand
    const weapon = buildWeapon(this.weaponKind, this.weaponKind === 'axe' ? 1.15 : 1)
    weapon.position.set(0, 0, 0)
    weapon.rotation.x = 0.18
    armGroups.r.hand.add(weapon)
    this.weapon = weapon
    this.weaponRest = weapon.rotation.clone()

    // telegraph glint
    const glowCanvas = document.createElement('canvas')
    glowCanvas.width = glowCanvas.height = 64
    const gc = glowCanvas.getContext('2d')
    const grad = gc.createRadialGradient(32, 32, 2, 32, 32, 32)
    grad.addColorStop(0, 'rgba(255,220,190,1)')
    grad.addColorStop(0.35, 'rgba(255,80,40,0.7)')
    grad.addColorStop(1, 'rgba(255,20,10,0)')
    gc.fillStyle = grad
    gc.fillRect(0, 0, 64, 64)
    const glowTex = new THREE.CanvasTexture(glowCanvas)
    this.glint = new THREE.Sprite(new THREE.SpriteMaterial({
      map: glowTex, color: 0xff6a3a, transparent: true, blending: THREE.AdditiveBlending,
      depthWrite: false, opacity: 0
    }))
    this.glint.scale.set(0.7, 0.7, 1)
    this.glint.position.set(0, -1.0, 0)
    weapon.add(this.glint)

    // scale whole body
    if (s !== 1) {
      hips.scale.setScalar(s)
      hips.position.y *= s
      root.scale.setScalar(1)
    }

    root.traverse((o) => {
      if (o.isMesh) { o.castShadow = !this.game?.low; o.receiveShadow = true }
    })

    this.baseHipY = hips.position.y
  }

  taperBox(topW, bottomW, h, depth) {
    const geo = new THREE.BoxGeometry(1, 1, 1)
    const pos = geo.attributes.position
    for (let i = 0; i < pos.count; i++) {
      const y = pos.getY(i)
      const k = y > 0 ? topW : bottomW
      pos.setX(i, pos.getX(i) * k)
      pos.setY(i, pos.getY(i) * h)
      pos.setZ(i, pos.getZ(i) * depth)
    }
    pos.needsUpdate = true
    geo.computeVertexNormals()
    return geo
  }

  updateHitParts() {
    if (this.dead && this.state === 'dead') { this.hitParts = []; return }
    this.root.updateWorldMatrix(true, true)
    const parts = []
    const add = (key, mesh, radius, offsetY = 0) => {
      const p = new THREE.Vector3()
      mesh.getWorldPosition(p)
      p.y += offsetY
      parts.push({ key, pos: p, radius: radius * this.scale })
    }
    add('head', this.head, 0.19, 0)
    add('torso', this.torso, 0.3, 0.02)
    add('torso', this.torso, 0.25, -0.2)
    add('armL', this.arms.l.upper, 0.13)
    add('armL', this.arms.l.fore, 0.12)
    add('armR', this.arms.r.upper, 0.13)
    add('armR', this.arms.r.fore, 0.12)
    add('legL', this.legs.l.thighMesh, 0.14)
    add('legL', this.legs.l.shin, 0.12)
    add('legR', this.legs.r.thighMesh, 0.14)
    add('legR', this.legs.r.shin, 0.12)
    this.hitParts = parts
  }

  weaponSegment(outA, outB) {
    this.weapon.updateWorldMatrix(true, false)
    outA.set(0, -0.05, 0)
    outB.set(0, -this.weapon.userData.length, 0)
    this.weapon.localToWorld(outA)
    this.weapon.localToWorld(outB)
  }

  /** Returns the best part hit by a world-space segment. */
  hitTest(a, b, padding = 0.06) {
    if (this.dead) return null
    let best = null
    let bestScore = Infinity
    const v = new THREE.Vector3()
    for (const part of this.hitParts) {
      v.copy(part.pos)
      const ab = new THREE.Vector3().subVectors(b, a)
      const apx = v.x - a.x, apy = v.y - a.y, apz = v.z - a.z
      const denom = ab.lengthSq()
      let t = denom > 1e-8 ? (apx * ab.x + apy * ab.y + apz * ab.z) / denom : 0
      t = clamp(t, 0, 1)
      const dx = apx - ab.x * t, dy = apy - ab.y * t, dz = apz - ab.z * t
      const dist = Math.sqrt(dx * dx + dy * dy + dz * dz)
      if (dist > part.radius + padding) continue
      let score = dist / part.radius
      if (part.key === 'head') score -= 0.22
      if (part.key === 'torso') score += 0.1
      if (score < bestScore) {
        bestScore = score
        best = { ...part, point: new THREE.Vector3(v.x, v.y, v.z), distance: dist }
      }
    }
    return best
  }

  takeHit(partKey, damage, hitType, dir, point, opts = {}) {
    if (this.dead) return null
    const key = partKey === 'armL' || partKey === 'armR' ? partKey : partKey
    const side = key.endsWith('L') ? 'l' : key.endsWith('R') ? 'r' : null
    // block?
    if (this.blocking && opts.fromPlayer && this.state === 'block' && opts.frontal !== false) {
      sound.block()
      this.game?.onEnemyBlocked(this, point)
      this.staggerTimer = Math.max(this.staggerTimer, 0.18)
      return { blocked: true }
    }

    const isHead = key === 'head'
    const isTorso = key === 'torso'
    const isArm = key.startsWith('arm')
    const isLeg = key.startsWith('leg')
    const mult = isHead ? 1.55 : isTorso ? 1.0 : isArm ? 0.92 : 0.85
    const armor = this.type.armor
    const applied = Math.max(1, damage * mult * armor)

    if (key in this.partHp) this.partHp[key] -= applied

    this.hitReact = 0.28
    this.hitReactDir = rand(-1, 1)
    this.flash = 0.12
    this.bloodied++

    // stagger logic
    const heavy = damage > 40 || hitType === 'crush'
    if (this.cfg.boss) this.staggerTimer = Math.max(this.staggerTimer, heavy ? 0.25 : 0)
    else if (heavy || isHead) this.staggerTimer = Math.max(this.staggerTimer, heavy ? 0.85 : 0.5)
    else if (chance(0.25)) this.staggerTimer = Math.max(this.staggerTimer, 0.35)

    if (this.staggerTimer > 0.3 && !this.cfg.boss) {
      this.state = 'stagger'
      this.stateTime = 0
      this.attackTimer = 0
    }

    let destroyed = false
    let deathKind = null

    if (key === 'head' && this.partHp.head <= 0) {
      destroyed = true
      deathKind = hitType === 'crush' ? 'explode' : 'decap'
    } else if (isArm && this.partHp[key] <= 0) {
      destroyed = true
      // arm destroyed at shoulder
    } else if (isLeg && this.partHp[key] <= 0) {
      destroyed = true
    } else if (isTorso && this.partHp.torso <= 0) {
      destroyed = true
      deathKind = hitType === 'crush' ? 'chestburst' : 'bisect'
    }

    if (this.partHp[key] !== undefined && this.partHp[key] <= 0) {
      this.partHp[key] = 0
    }

    return { applied, destroyed, deathKind, key, side, heavy }
  }

  checkDestroy(result, dir, point) {
    if (!result || !result.destroyed || this.dead) return
    const { key, side, deathKind } = result
    const game = this.game
    if (key === 'head') {
      if (deathKind === 'explode') {
        this.explodeHead(dir, point)
      } else {
        this.decapitate(dir, point)
      }
      return
    }
    if (key.startsWith('arm')) {
      this.severArm(side, dir, point)
      return
    }
    if (key.startsWith('leg')) {
      this.severLeg(side, dir, point)
      return
    }
    if (key === 'torso') {
      if (deathKind === 'chestburst') this.chestBurst(dir, point)
      else this.bisect(dir, point)
    }
  }

  get stumpMat() {
    if (!this._stumpMat) this._stumpMat = new THREE.MeshStandardMaterial({ color: 0x5a0309, roughness: 0.45 })
    return this._stumpMat
  }

  addStump(parent, x, y, z, r = 0.09) {
    const stump = new THREE.Mesh(new THREE.SphereGeometry(r, 8, 6), this.stumpMat)
    stump.position.set(x, y, z)
    stump.scale.set(1, 0.7, 1)
    parent.add(stump)
    return stump
  }

  worldOf(object, offsetY = 0) {
    const v = new THREE.Vector3()
    object.getWorldPosition(v)
    v.y += offsetY
    return v
  }

  severArm(side, dir, point) {
    if (this.armGone[side]) return
    this.armGone[side] = true
    const arm = this.arms[side]
    const socket = this.worldOf(arm.shoulder)
    const wasWeapon = side === 'r' && !!this.weapon
    const group = arm.shoulder
    // ensure world matrices up to date
    this.root.updateWorldMatrix(true, true)
    const weaponPos = this.weapon ? this.worldOf(this.weapon, -0.7) : null
    this.scene.attach(group)
    if (wasWeapon && this.weapon) {
      this.weapon.userData.stain && (this.weapon.userData.stain.visible = true)
    }
    this.gore.limbSever(socket, dir, group, 0.25)
    if (wasWeapon) {
      // the arm still holds the weapon; drop later is impossible. Mark as lost.
      this.weaponDropped = true
      this.weapon = null
    }
    // stump on shoulder
    this.addStump(this.spine, side === 'l' ? -0.3 : 0.3, 0.47, 0, 0.1)
    this.game?.onDismember(this, side === 'r' ? 'ARM' : 'LEFT ARM', socket, 'sever')
    this.staggerTimer = Math.max(this.staggerTimer, 0.7)
    if (!this.dead) {
      this.state = 'stagger'
      this.stateTime = 0
    }
    sound.sever()
    if (wasWeapon) {
      this.game?.onFloater(socket, 'DISARMED', 'gold')
    }
  }

  severLeg(side, dir, point) {
    if (this.legGone[side]) return
    this.legGone[side] = true
    const leg = this.legs[side]
    const socket = this.worldOf(leg.thigh, -0.1)
    this.root.updateWorldMatrix(true, true)
    this.scene.attach(leg.thigh)
    this.gore.limbSever(socket, dir, leg.thigh, 0.24)
    this.addStump(this.hips, side === 'l' ? -0.125 : 0.125, -0.06, 0, 0.11)
    this.moveSpeed *= 0.45
    this.game?.onDismember(this, side === 'r' ? 'LEG' : 'LEFT LEG', socket, 'sever')
    sound.sever()
    if (this.legGone.l && this.legGone.r) {
      this.die('collapse', dir, socket)
    } else {
      this.staggerTimer = Math.max(this.staggerTimer, 1.0)
      this.state = 'stagger'
      this.stateTime = 0
      this.game?.onFloater(socket, 'HAMSTRUNG', 'gold')
    }
  }

  decapitate(dir, point) {
    if (this.dead) return
    const neck = this.neck
    const pos = this.worldOf(neck, 0.06)
    this.root.updateWorldMatrix(true, true)
    this.scene.attach(neck)
    this.headGone = true
    this.gore.headDetach(pos, dir, neck)
    // neck stump
    this.addStump(this.spine, 0, 0.54, 0, 0.12)
    this.weaponDropAt = this.worldOf(this.weapon || this.arms.r.hand, -0.4)
    sound.sever()
    this.game?.onDismember(this, 'HEAD', pos, 'decap')
    this.die('decap', dir, pos, true)
  }

  explodeHead(dir, point) {
    if (this.dead) return
    const pos = this.worldOf(this.neck, 0.13)
    this.root.updateWorldMatrix(true, true)
    if (this.neck.parent) {
      this.scene.attach(this.neck)
      this.neck.visible = false
    }
    this.headGone = true
    this.gore.headExplode(pos, dir)
    this.addStump(this.spine, 0, 0.54, 0, 0.13)
    this.game?.onDismember(this, 'SKULL CRUSHED', pos, 'crush')
    this.die('explode', dir, pos, true)
    this.game?.onFloater(pos, 'SKULL CRUSHED', 'gore')
  }

  chestBurst(dir, point) {
    if (this.dead) return
    const pos = this.worldOf(this.torso, 0.05)
    this.gore.blood.burst(pos, { count: 110, chaos: 5, size: 1.5 })
    this.gore.bloodSpray(pos, { x: dir.x, y: 0.4, z: dir.z }, 45, 6, 1.4)
    for (let i = 0; i < 14; i++) this.gore.gib(pos, dir, i % 3 === 0 ? 'bone' : 'meat')
    this.gore.groundSplash(pos)
    this.gore.spillGuts(pos, dir)
    this.game?.onDismember(this, 'RIB CAGE SHATTERED', pos, 'crush')
    this.game?.onFloater(pos, 'CHEST CAVED IN', 'gore')
    sound.crush()
    this.die('chestburst', dir, pos, true)
  }

  bisect(dir, point) {
    if (this.dead) return
    this.dead = true
    this.dying = true
    this.state = 'dead'
    this.hitParts = []
    const cut = this.worldOf(this.hips, 0.16)
    this.root.updateWorldMatrix(true, true)
    const upper = this.spine
    const lower = this.hips
    this.scene.attach(upper)
    this.scene.attach(lower)
    this.scene.remove(this.root)
    this.gore.bisect(cut, dir, upper, lower)
    this.game?.onDismember(this, 'BISECTED', cut, 'bisect')
    this.game?.onFloater(cut, 'CUT IN HALF', 'gore')
    this.game?.onKill(this, 'BISECTED', cut)
    this.dropWeaponAt(cut, dir)
  }

  die(mode, dir, point, silentKill) {
    if (this.dead) return
    this.dead = true
    this.dying = true
    this.state = 'dead'
    this.deathTimer = 0
    this.deathMode = mode
    this.hitParts = []
    this.blocking = false
    const p = point || this.worldOf(this.hips)
    this.gore.groundSplash(p)
    this.gore.pools.add(p.x, p.z, rand(1.3, 2.0))
    this.dropWeaponAt(p, dir)
    this.game?.onKill(this, mode === 'explode' ? 'SKULL CRUSHED' : mode === 'chestburst' ? 'CHEST CAVED IN' : 'SLAIN', p)
    sound.deathRattle()
    if (!silentKill) sound.scream(rand(0.8, 1.2))
    this.fallDir = Math.atan2(dir.x, dir.z)
    this.fallSign = chance(0.5) ? 1 : -1
  }

  dropWeaponAt(pos, dir) {
    if (!this.weapon || this.weaponDropped || this.weaponLocked) return
    const weapon = this.weapon
    if (!weapon.parent) return
    this.root.updateWorldMatrix(true, true)
    const wp = new THREE.Vector3()
    weapon.getWorldPosition(wp)
    this.scene.attach(weapon)
    weapon.position.copy(wp)
    this.weapon = null
    this.weaponDropped = true
    const angle = rand(0, TAU)
    this.gore.debris.add(weapon, {
      x: Math.cos(angle) * rand(0.4, 1.4), y: rand(0.8, 2), z: Math.sin(angle) * rand(0.4, 1.4)
    }, { x: rand(-5, 5), y: rand(-5, 5), z: rand(-5, 5) }, 0.15, { restY: 0.06 })
    this.game?.onWeaponDrop(this.weaponKind, weapon)
  }

  /** Finisher used by the player on a staggered enemy. */
  execute(kind, dir) {
    if (this.dead) return
    const headPos = this.worldOf(this.neck, 0.12)
    this.dead = true
    this.dying = true
    this.state = 'dead'
    this.hitParts = []
    if (kind === 'hammer') {
      this.gore.headExplode(headPos, dir)
      if (this.neck.parent) { this.scene.attach(this.neck); this.neck.visible = false }
      this.addStump(this.spine, 0, 0.54, 0, 0.14)
      this.game?.onFloater(headPos, 'SKULL CRUSHED', 'gore')
    } else {
      this.root.updateWorldMatrix(true, true)
      this.scene.attach(this.neck)
      this.gore.headDetach(headPos, dir, this.neck)
      this.addStump(this.spine, 0, 0.54, 0, 0.12)
      this.game?.onFloater(headPos, 'DECAPITATED', 'gore')
    }
    this.game?.onDismember(this, kind === 'hammer' ? 'EXECUTION' : 'DECAPITATION', headPos, 'execute')
    sound.sever()
    sound.scream(0.7)
    this.game?.onKill(this, kind === 'hammer' ? 'SKULL CRUSHED' : 'DECAPITATED', headPos, true)
    this.gore.groundSplash(headPos)
    this.dropWeaponAt(headPos, dir)
    this.fallDir = Math.atan2(dir.x, dir.z)
    this.fallSign = chance(0.5) ? 1 : -1
  }

  update(dt, time, player, others) {
    this.stateTime += dt
    if (this.staggerTimer > 0) this.staggerTimer -= dt
    this.attackCooldown -= dt
    this.hitReact = Math.max(0, this.hitReact - dt)
    this.flash = Math.max(0, this.flash - dt)
    if (this.blockCooldown > 0) this.blockCooldown -= dt

    if (this.dead) {
      this.updateDeath(dt)
      return
    }

    // face the player
    const dx = player.pos.x - this.root.position.x
    const dz = player.pos.z - this.root.position.z
    const dist = Math.hypot(dx, dz)
    const targetYaw = Math.atan2(dx, dz)
    let dy = targetYaw - this.root.rotation.y
    while (dy > Math.PI) dy -= TAU
    while (dy < -Math.PI) dy += TAU
    const turnRate = this.state === 'windup' ? 8 : 4.4
    this.root.rotation.y += dy * Math.min(1, turnRate * dt)

    // state machine
    if (this.staggerTimer > 0) {
      if (this.state !== 'stagger') { this.state = 'stagger'; this.stateTime = 0 }
    } else if (this.state === 'stagger') {
      this.state = 'chase'
      this.stateTime = 0
      this.attackCooldown = Math.max(this.attackCooldown, 0.18)
    }

    let moveX = 0, moveZ = 0
    let wantSpeed = 0
    const forwardX = Math.sin(this.root.rotation.y)
    const forwardZ = Math.cos(this.root.rotation.y)
    const rightX = Math.cos(this.root.rotation.y)
    const rightZ = -Math.sin(this.root.rotation.y)

    if (this.state === 'spawn') {
      if (this.stateTime > 0.7) { this.state = 'chase'; this.stateTime = 0 }
    }

    if (this.state === 'chase' || this.state === 'strafe') {
      this.strafeTimer -= dt
      const stopRange = this.cfg.reach * 0.72
      if (dist > stopRange) {
        moveX = dx / (dist || 1)
        moveZ = dz / (dist || 1)
        wantSpeed = this.moveSpeed
      } else {
        // circle
        this.state = 'strafe'
        moveX = rightX * this.sideDir * 0.7 - (dx / (dist || 1)) * 0.25
        moveZ = rightZ * this.sideDir * 0.7 - (dz / (dist || 1)) * 0.25
        wantSpeed = this.moveSpeed * 0.55
      }
      if (this.strafeTimer <= 0) {
        this.strafeTimer = rand(1.2, 2.8)
        this.sideDir *= -1
        if (chance(0.3)) this.state = 'chase'
      }
      // block when player is winding up nearby
      if (player.attackState === 'windup' && dist < 3.6 && this.blockCooldown <= 0 && !this.armGone.r) {
        if (this.wantBlock || chance(0.45)) {
          this.state = 'block'
          this.stateTime = 0
          this.blockCooldown = rand(2.5, 4.5)
          this.blocking = true
        }
      }
    }

    if (this.state === 'block') {
      this.blocking = true
      if (this.stateTime > 0.85 || dist > 3.4) {
        this.state = 'chase'
        this.stateTime = 0
        this.blocking = false
      }
    } else {
      this.blocking = false
    }

    // begin attack
    const canAttack = !this.armGone.r && this.attackCooldown <= 0 &&
      (this.state === 'chase' || this.state === 'strafe') && dist < this.cfg.reach && dist > 0.8
    if (canAttack) {
      this.state = 'windup'
      this.stateTime = 0
      this.struck = false
      this.attackIndex = (this.attackIndex + 1) % 3
      this.attackCooldown = rand(this.cfg.cooldown[0], this.cfg.cooldown[1])
      if (chance(0.3)) sound.scream(rand(0.9, 1.3))
    }

    if (this.state === 'windup') {
      this.glint.material.opacity = clamp(this.stateTime / this.cfg.windup, 0, 1) * 0.75
      this.glint.scale.setScalar(0.5 + Math.sin(time * 22) * 0.08 + this.stateTime * 0.4)
      if (this.stateTime >= this.cfg.windup) {
        this.state = 'strike'
        this.stateTime = 0
        sound.swing(this.weaponKind, 0.4)
        this.glint.material.opacity = 0
      }
    } else {
      this.glint.material.opacity = Math.max(0, this.glint.material.opacity - dt * 4)
    }

    if (this.state === 'strike') {
      these: {
        if (!this.struck && this.stateTime > this.cfg.windup * 0.06 + 0.05) {
          this.struck = true
          this.resolveAttack(player)
        }
      }
      if (this.stateTime > 0.22) {
        this.state = 'recover'
        this.stateTime = 0
      }
    } else if (this.state === 'recover') {
      if (this.stateTime > this.cfg.recover) {
        this.state = 'chase'
        this.stateTime = 0
        this.attackCooldown = Math.max(this.attackCooldown, rand(0.2, 0.6))
      }
    }

    // movement
    if (this.staggerTimer <= 0 && (this.state === 'chase' || this.state === 'strafe' || this.state === 'spawn')) {
      const sep = this.separation(others)
      moveX += sep.x
      moveZ += sep.z
      const len = Math.hypot(moveX, moveZ)
      if (len > 1) { moveX /= len; moveZ /= len }
      const px = player.pos.x - this.root.position.x
      const pz = player.pos.z - this.root.position.z
      const pd = Math.hypot(px, pz) || 1
      if (pd < 0.95) {
        moveX -= (px / pd) * 0.8
        moveZ -= (pz / pd) * 0.8
      }
      this.root.position.x += moveX * wantSpeed * dt
      this.root.position.z += moveZ * wantSpeed * dt
      const r = Math.hypot(this.root.position.x, this.root.position.z)
      if (r > ARENA_RADIUS - 0.6) {
        this.root.position.x *= (ARENA_RADIUS - 0.6) / r
        this.root.position.z *= (ARENA_RADIUS - 0.6) / r
      }
      this.walkPhase += dt * (wantSpeed > 0.1 ? 6.2 : 2.4) * (this.moveSpeed / 2)
      this.animWalk(wantSpeed / Math.max(0.1, this.moveSpeed))
    } else {
      this.animWalk(0)
    }

    // pose / animations
    this.animate(dt, time, player)
    this.updateHitParts()

    // weapon stain builds up
    if (this.weapon && this.weapon.userData.stain) {
      this.weapon.userData.stain.visible = this.bloodied > 0
    }
  }

  separation(others) {
    let sx = 0, sz = 0
    for (const o of others) {
      if (o === this || o.dead) continue
      const dx = this.root.position.x - o.root.position.x
      const dz = this.root.position.z - o.root.position.z
      const d = Math.hypot(dx, dz)
      if (d > 0.001 && d < 1.5) {
        sx += (dx / d) * (1.5 - d) * 0.9
        sz += (dz / d) * (1.5 - d) * 0.9
      }
    }
    return { x: sx, z: sz }
  }

  resolveAttack(player) {
    const dx = player.pos.x - this.root.position.x
    const dz = player.pos.z - this.root.position.z
    const dist = Math.hypot(dx, dz)
    const reach = this.cfg.reach * (this.weaponKind === 'hammer' ? 1.02 : 1)
    if (dist > reach + 0.45) return
    const forwardX = Math.sin(this.root.rotation.y)
    const forwardZ = Math.cos(this.root.rotation.y)
    const dot = (dx * forwardX + dz * forwardZ) / (dist || 1)
    if (dot < 0.35) return
    const dmg = this.cfg.damage * (this.armGone.r ? 0.3 : 1) * (0.85 + Math.random() * 0.3)
    this.game?.enemyHitPlayer(this, dmg, this.weaponKind)
  }

  animWalk(amount) {
    const w = this.walkPhase
    const swing = Math.sin(w) * 0.55 * amount
    this.legs.l.thigh.rotation.x = swing
    this.legs.r.thigh.rotation.x = -swing
    this.legs.l.knee.rotation.x = Math.max(0, -Math.sin(w)) * 0.7 * amount
    this.legs.r.knee.rotation.x = Math.max(0, Math.sin(w)) * 0.7 * amount
    const bob = Math.abs(Math.sin(w)) * 0.035 * amount
    this.hips.position.y = this.baseHipY + bob
    if (!this.armGone.l) this.arms.l.shoulder.rotation.x = -swing * 0.7
    if (!this.armGone.r) this.arms.r.shoulder.rotation.x = swing * 0.55
    this._walkAmount = amount
  }

  animate(dt, time, player) {
    // base posture
    let spineX = 0, spineY = 0, spineZ = 0
    let shR = { x: 0, y: 0, z: 0 }
    let elR = -0.25
    let shL = { x: 0, y: 0, z: 0 }, elL = -0.18
    let hipDrop = 0

    if (this.state === 'chase' || this.state === 'strafe' || this.state === 'spawn') {
      spineX = 0.06
      shR.x += -0.3
      elR = -0.5
      shL.x = -0.15
      elL = -0.35
    }

    if (this.state === 'windup') {
      const t = clamp(this.stateTime / this.cfg.windup, 0, 1)
      const e = t * t
      if (this.weaponKind === 'hammer' || this.weaponKind === 'axe') {
        shR.x = lerp(-0.3, -2.55, e)
        shR.z = lerp(0, -0.25, e)
        elR = lerp(-0.5, -0.35, e)
        spineX = lerp(0.06, -0.22, e)
        spineY = lerp(0, 0.32, e)
      } else {
        shR.x = lerp(-0.3, -1.75, e)
        shR.z = lerp(0, 0.55, e)
        elR = lerp(-0.5, -1.1, e)
        spineX = lerp(0.06, -0.12, e)
        spineY = lerp(0, 0.55, e)
      }
      shL.x = -0.5; elL = -0.8
    } else if (this.state === 'strike') {
      const t = clamp(this.stateTime / 0.2, 0, 1)
      const e = 1 - Math.pow(1 - t, 2)
      if (this.weaponKind === 'hammer' || this.weaponKind === 'axe') {
        shR.x = lerp(-2.55, 0.55, e)
        shR.z = lerp(-0.25, 0.1, e)
        elR = lerp(-0.35, -0.15, e)
        spineX = lerp(-0.22, 0.42, e)
        spineY = lerp(0.32, -0.35, e)
        hipDrop = Math.sin(t * Math.PI) * 0.08
      } else {
        shR.x = lerp(-1.75, -0.2, e)
        shR.z = lerp(0.55, -0.7, e)
        elR = lerp(-1.1, -0.35, e)
        spineX = lerp(-0.12, 0.14, e)
        spineY = lerp(0.55, -0.6, e)
        hipDrop = Math.sin(t * Math.PI) * 0.04
      }
      shL.x = -0.3; elL = -0.6
    } else if (this.state === 'recover') {
      const t = clamp(this.stateTime / this.cfg.recover, 0, 1)
      shR.x = lerp(0.4, -0.3, t)
      shR.z = lerp(0.2, 0, t)
      elR = -0.45
      spineX = lerp(0.2, 0.06, t)
      spineY = lerp(-0.2, 0, t)
    } else if (this.state === 'block') {
      shL.x = -1.35
      shL.z = 0.65
      elL = -1.55
      shR.x = -0.5
      elR = -0.8
      spineX = 0.12
      spineY = 0.25
    } else if (this.state === 'stagger' || this.staggerTimer > 0) {
      const t = clamp(this.stateTime / 0.4, 0, 1)
      spineX = -0.25 - Math.sin(t * 20) * 0.06
      spineZ = 0.18 * (1 - t) + this.hitReactDir * 0.1
      shR.x = 0.4
      shL.x = 0.5
      elR = -0.2
      hipDrop = 0.06
    }

    // hit flinch overlay
    if (this.hitReact > 0) {
      const k = this.hitReact / 0.28
      spineX += 0.35 * k
      spineZ += this.hitReactDir * 0.25 * k
      hipDrop += 0.02 * k
    }

    // apply with smoothness
    const k = 1 - Math.exp(-18 * dt)
    this.spine.rotation.x += (spineX - this.spine.rotation.x) * k
    this.spine.rotation.y += (spineY - this.spine.rotation.y) * k
    this.spine.rotation.z += (spineZ - this.spine.rotation.z) * k
    if (!this.armGone.r) {
      this.arms.r.shoulder.rotation.x += (shR.x - this.arms.r.shoulder.rotation.x) * k
      this.arms.r.shoulder.rotation.z += (shR.z - this.arms.r.shoulder.rotation.z) * k
      this.arms.r.elbow.rotation.x += (elR - this.arms.r.elbow.rotation.x) * k
    }
    if (!this.armGone.l) {
      this.arms.l.shoulder.rotation.x += (shL.x - this.arms.l.shoulder.rotation.x) * k
      this.arms.l.shoulder.rotation.z += (shL.z - this.arms.l.shoulder.rotation.z) * k
      this.arms.l.elbow.rotation.x += (elL - this.arms.l.elbow.rotation.x) * k
    }
    this.hips.position.y += (this.baseHipY - hipDrop - this.hips.position.y) * Math.min(1, dt * 10)

    // head look at player
    if (!this.headGone) {
      const headYaw = clamp((player.pos.x - this.root.position.x) * 0.1, -0.4, 0.4)
      this.neck.rotation.y += (headYaw - this.neck.rotation.y) * Math.min(1, dt * 6)
    }

    // weapon sway / grip
    if (this.weapon) {
      this.weapon.rotation.x = 0.18 + Math.sin(time * 2 + this.walkPhase) * 0.02
    }
  }

  updateDeath(dt) {
    this.deathTimer += dt
    if (this.deathMode === 'bisect') return
    const t = clamp(this.deathTimer / 0.9, 0, 1)
    const e = t * t
    const targetZ = (this.fallSign || 1) * Math.PI * 0.5
    this.root.rotation.z = e * targetZ
    this.root.rotation.x = e * 0.15
    this.root.position.y = -e * 0.05
    this.hips.position.y = this.baseHipY - e * 0.12
    if (this.armGone.r) this.arms.r.shoulder.rotation.x = 0.5
    if (this.armGone.l) this.arms.l.shoulder.rotation.x = 0.5
    if (this.deathTimer > 1.2 && !this._pooled) {
      this._pooled = true
      const p = this.worldOf(this.hips)
      this.gore.pools.add(p.x, p.z, rand(1.4, 2.2))
      for (let i = 0; i < 3; i++) {
        this.gore.decals.add(p.x + rand(-0.8, 0.8), p.z + rand(-0.8, 0.8), rand(0.7, 1.6), rand(0, TAU))
      }
    }
  }

  get position() { return this.root.position }
}

import * as THREE from 'three'
import {
  TAU, clamp, lerp, damp, rand, chance, easeOutCubic, easeOutQuint, easeInOutQuad,
  makeMesh, softDropTexture
} from './utils.js'
import { sound } from './audio.js'
import { ARENA_RADIUS } from './arena.js'

const WEAPON_STATS = {
  sword: {
    name: 'SWORD', kind: 'CLEAVER', type: 'slash',
    light: { damage: 31, windup: 0.055, active: 0.15, recover: 0.2, range: 2.35, hitRadius: 0.09 },
    heavy: { damage: 82, windup: 0.16, active: 0.2, recover: 0.36, range: 2.55, hitRadius: 0.14 },
    reach: 2.4,
    speeds: [1.0, 1.05, 1.18]
  },
  hammer: {
    name: 'HAMMER', kind: 'SKULLBREAKER', type: 'crush',
    light: { damage: 46, windup: 0.14, active: 0.16, recover: 0.3, range: 2.25, hitRadius: 0.16 },
    heavy: { damage: 96, windup: 0.27, active: 0.22, recover: 0.44, range: 2.5, hitRadius: 0.24 },
    reach: 2.3,
    speeds: [0.92, 0.98, 1.1]
  }
}

function buildWeaponModel(type) {
  const g = new THREE.Group()
  const steel = new THREE.MeshStandardMaterial({ color: 0xb7c0c9, roughness: 0.28, metalness: 0.92 })
  const darkSteel = new THREE.MeshStandardMaterial({ color: 0x565b62, roughness: 0.4, metalness: 0.85 })
  const wood = new THREE.MeshStandardMaterial({ color: 0x3f2718, roughness: 0.92 })
  const leather = new THREE.MeshStandardMaterial({ color: 0x26170f, roughness: 0.95 })
  const brass = new THREE.MeshStandardMaterial({ color: 0xb08a48, roughness: 0.3, metalness: 0.9 })
  const blood = new THREE.MeshStandardMaterial({ color: 0x6d0810, roughness: 0.42 })

  if (type === 'sword') {
    const grip = makeMesh(new THREE.CylinderGeometry(0.026, 0.031, 0.24, 8), leather, [0, -0.02, 0])
    const pommel = makeMesh(new THREE.SphereGeometry(0.045, 8, 6), brass, [0, -0.15, 0])
    const guard = makeMesh(new THREE.BoxGeometry(0.34, 0.045, 0.07), brass, [0, 0.11, 0])
    const blade = new THREE.Mesh(new THREE.BoxGeometry(0.068, 0.92, 0.017), steel)
    blade.position.y = 0.6
    // taper the blade to a point
    const p = blade.geometry.attributes.position
    for (let i = 0; i < p.count; i++) {
      const yy = p.getY(i)
      if (yy > 0.3) {
        p.setX(i, p.getX(i) * 0.28)
        p.setZ(i, p.getZ(i) * 0.45)
      }
    }
    p.needsUpdate = true
    blade.geometry.computeVertexNormals()
    const fuller = new THREE.Mesh(new THREE.BoxGeometry(0.014, 0.62, 0.021), darkSteel)
    fuller.position.y = 0.52
    const tip = new THREE.Mesh(new THREE.ConeGeometry(0.019, 0.16, 4), steel)
    tip.position.y = 1.12
    tip.rotation.y = Math.PI / 4
    const stain = new THREE.Mesh(new THREE.PlaneGeometry(0.05, 0.52), blood)
    stain.position.set(0.037, 0.62, 0.008)
    stain.rotation.y = Math.PI / 2
    stain.visible = false
    g.add(grip, pommel, guard, blade, fuller, tip, stain)
    g.userData.stain = stain
    g.userData.tip = 1.14
    g.userData.base = 0.16
  } else {
    const handle = makeMesh(new THREE.CylinderGeometry(0.033, 0.041, 0.95, 8), wood, [0, 0.36, 0])
    const wrap = makeMesh(new THREE.CylinderGeometry(0.042, 0.042, 0.24, 8), leather, [0, -0.05, 0])
    const pommel = makeMesh(new THREE.CylinderGeometry(0.045, 0.04, 0.06, 8), brass, [0, -0.19, 0])
    const head = new THREE.Mesh(new THREE.BoxGeometry(0.4, 0.27, 0.25), darkSteel)
    head.position.y = 0.9
    const bevel = new THREE.Mesh(new THREE.BoxGeometry(0.43, 0.1, 0.28), steel)
    bevel.position.y = 0.9
    const faceL = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.31, 0.29), steel)
    faceL.position.set(-0.235, 0.9, 0)
    const faceR = faceL.clone()
    faceR.position.x = 0.235
    const band = makeMesh(new THREE.CylinderGeometry(0.05, 0.05, 0.08, 8), brass, [0, 0.73, 0])
    const spike = new THREE.Mesh(new THREE.ConeGeometry(0.045, 0.16, 5), steel)
    spike.position.set(0.29, 0.9, 0)
    spike.rotation.z = -Math.PI / 2
    const stain = new THREE.Mesh(new THREE.BoxGeometry(0.41, 0.08, 0.27), blood)
    stain.position.y = 1.04
    stain.visible = false
    g.add(handle, wrap, pommel, head, bevel, faceL, faceR, band, spike, stain)
    g.userData.stain = stain
    g.userData.tip = 1.06
    g.userData.base = 0.7
  }
  g.traverse((o) => { if (o.isMesh) { o.castShadow = false; o.receiveShadow = false } })
  return g
}

class BladeTrail {
  constructor(scene) {
    this.max = 18
    this.points = []
    const geo = new THREE.BufferGeometry()
    this.positions = new Float32Array(this.max * 2 * 3)
    this.alphas = new Float32Array(this.max * 2)
    geo.setAttribute('position', new THREE.BufferAttribute(this.positions, 3))
    geo.setAttribute('aAlpha', new THREE.BufferAttribute(this.alphas, 1))
    geo.setDrawRange(0, 0)
    const mat = new THREE.ShaderMaterial({
      transparent: true, depthWrite: false, side: THREE.DoubleSide,
      uniforms: {},
      vertexShader: `attribute float aAlpha; varying float vA; void main(){ vA=aAlpha; gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0); }`,
      fragmentShader: `varying float vA; void main(){ if(vA<0.01) discard; gl_FragColor=vec4(0.92,0.85,0.8,vA*0.28); }`
    })
    this.mesh = new THREE.Mesh(geo, mat)
    this.mesh.frustumCulled = false
    this.mesh.renderOrder = 4
    scene.add(this.mesh)
    this.geo = geo
    this.enabled = false
  }

  push(base, tip, t) {
    this.points.push({ base: base.clone(), tip: tip.clone(), born: t })
    if (this.points.length > this.max) this.points.shift()
  }

  update(t, active) {
    while (this.points.length && t - this.points[0].born > 0.18) this.points.shift()
    const n = this.points.length
    this.geo.setDrawRange(0, Math.max(0, (n - 1) * 6))
    for (let i = 0; i < n; i++) {
      const p = this.points[i]
      const age = clamp(1 - (t - p.born) / 0.18, 0, 1)
      this.positions[i * 6] = p.base.x
      this.positions[i * 6 + 1] = p.base.y
      this.positions[i * 6 + 2] = p.base.z
      this.positions[i * 6 + 3] = p.tip.x
      this.positions[i * 6 + 4] = p.tip.y
      this.positions[i * 6 + 5] = p.tip.z
      this.alphas[i * 2] = age * 0.55
      this.alphas[i * 2 + 1] = age
    }
    this.geo.attributes.position.needsUpdate = true
    this.geo.attributes.aAlpha.needsUpdate = true
    // build indices implicitly? use non-indexed triangle strip converted to triangles
    if (n > 1) {
      const idx = []
      for (let i = 0; i < n - 1; i++) {
        const a = i * 2, b = i * 2 + 1, c = (i + 1) * 2, d = (i + 1) * 2 + 1
        idx.push(a, b, c, b, d, c)
      }
      this.geo.setIndex(idx)
    }
    this.mesh.visible = active && n > 1
  }

  clear() { this.points = []; this.mesh.visible = false }
}

export class Player {
  constructor(camera, scene, gore, game) {
    this.camera = camera
    this.scene = scene
    this.gore = gore
    this.game = game
    this.pos = new THREE.Vector3(0, 0, 6.5)
    this.yaw = Math.PI
    this.pitch = -0.04
    this.health = 100
    this.maxHealth = 100
    this.alive = true
    this.weaponId = 'sword'
    this.stats = WEAPON_STATS.sword
    this.moveSpeed = 5.35
    this.vel = new THREE.Vector3()
    this.moveInput = { x: 0, z: 0 }
    this.walkPhase = 0
    this.stepTimer = 0
    this.attackState = 'idle'
    this.attackT = 0
    this.attackKind = 'light'
    this.attackIndex = 0
    this.comboTimer = 0
    this.charging = false
    this.chargeTime = 0
    this.releaseHeld = false
    this.hitSet = new Set()
    this.blocking = false
    this.blockTime = 0
    this.parryWindow = 0.22
    this.dodgeTime = 0
    this.dodgeCooldown = 0
    this.dodgeDir = new THREE.Vector3()
    this.invuln = 0
    this.shoveTime = 0
    this.shoveCooldown = 0
    this.kick = 0
    this.deadTime = 0
    this.hurtFlash = 0
    this.noise = 0
    this.swapTime = 0
    this.executing = 0
    this.time = 0
    this.lastMoveDelta = 0
    this.rigBase = new THREE.Vector3(0.42, -0.42, -0.58)
    this.rig = new THREE.Group()
    this.rig.position.copy(this.rigBase)
    camera.add(this.rig)
    this.weaponModel = null
    this.trail = new BladeTrail(scene)
    this.tipA = new THREE.Vector3()
    this.tipB = new THREE.Vector3()
    this.baseA = new THREE.Vector3()
    this.baseB = new THREE.Vector3()
    this.shakeAmt = 0
    this.camKick = { x: 0, y: 0, z: 0, roll: 0 }
    this.rigSway = { x: 0, y: 0 }
    this.breath = 0
    this.blockingVisual = 0
    this.aimTarget = null
    this.footPhase = 0
    this.recoil = 0
    this.setWeapon('sword', true)
    this.updateCamera(0)
  }

  setWeapon(type, silent = false) {
    if (this.weaponModel) {
      this.rig.remove(this.weaponModel)
      this.weaponModel.traverse((o) => {
        if (o.geometry) o.geometry.dispose()
        if (o.material) o.material.dispose()
      })
    }
    this.weaponId = type
    this.stats = WEAPON_STATS[type]
    this.weaponModel = buildWeaponModel(type)
    this.rig.add(this.weaponModel)
    this.attackState = 'idle'
    this.charging = false
    this.swapTime = silent ? 0 : 0.32
    if (!silent) {
      sound.pickup()
      this.game?.onWeaponChanged(type)
    }
  }

  reset(weapon) {
    this.pos.set(0, 0, 6.5)
    this.yaw = Math.PI
    this.pitch = -0.03
    this.health = this.maxHealth
    this.alive = true
    this.deadTime = 0
    this.attackState = 'idle'
    this.charging = false
    this.chargeTime = 0
    this.blocking = false
    this.blockTime = 0
    this.dodgeTime = 0
    this.dodgeCooldown = 0
    this.invuln = 0
    this.shoveTime = 0
    this.shoveCooldown = 0
    this.executing = 0
    this.hurtFlash = 0
    this.shakeAmt = 0
    this.vel.set(0, 0, 0)
    this.trail.clear()
    this.setWeapon(weapon || this.weaponId, true)
    this.updateCamera(0)
  }

  look(dx, dy, sensitivity = 0.0022) {
    if (!this.alive || this.game?.paused) return
    this.yaw -= dx * sensitivity
    this.pitch -= dy * sensitivity
    this.pitch = clamp(this.pitch, -1.45, 1.35)
    this.rigSway.x = clamp(this.rigSway.x + dx * 0.00025, -0.05, 0.05)
    this.rigSway.y = clamp(this.rigSway.y + dy * 0.0002, -0.04, 0.04)
  }

  startCharge() {
    if (!this.alive || this.executing > 0) return
    if (this.attackState !== 'idle') return
    if (this.dodgeTime > 0) return
    this.charging = true
    this.chargeTime = 0
    this.blocking = false
  }

  releaseCharge() {
    if (!this.alive || !this.charging) return
    this.charging = false
    const heavy = this.chargeTime >= 0.26
    this.beginAttack(heavy ? 'heavy' : 'light', this.chargeTime)
  }

  cancelCharge() {
    this.charging = false
    this.chargeTime = 0
  }

  beginAttack(kind, charge = 0) {
    if (this.attackState !== 'idle' && this.attackState !== 'recover') return
    if (this.comboTimer > 0) this.attackIndex = (this.attackIndex + 1) % 3
    else this.attackIndex = 0
    this.attackKind = kind
    this.attackState = 'windup'
    this.attackT = 0
    this.chargeRatio = clamp(charge / 1.2, 0, 1)
    this.hitSet.clear()
    this.attackCount = 0
    this.blocking = false
    const cfg = this.stats[kind]
    this.attackDuration = cfg.windup + cfg.active + cfg.recover
    this.attackWindup = cfg.windup
    this.attackActive = cfg.active
    this.attackRecover = cfg.recover
    this.attackDamage = cfg.damage * (kind === 'heavy' ? (0.85 + this.chargeRatio * 0.35) : 1)
    this.attackRange = cfg.range
    this.attackHitRadius = cfg.hitRadius
    this.trail.clear()
    sound.swing(this.weaponId, kind === 'heavy' ? 0.8 : 0.2)
    if (kind === 'heavy') {
      this.game?.onHeavyStart(this)
      this.shake(0.15)
    }
  }

  blockDown() {
    if (!this.alive || this.attackState === 'windup' || this.attackState === 'active') return
    if (this.charging) this.cancelCharge()
    this.blocking = true
    this.blockTime = 0
    this.attackState = 'idle'
  }

  blockUp() {
    this.blocking = false
  }

  dodge() {
    if (!this.alive || this.dodgeCooldown > 0 || this.dodgeTime > 0) return
    if (this.executing > 0) return
    const input = this.moveInput
    let dx = input.x, dz = input.z
    if (Math.hypot(dx, dz) < 0.1) { dx = 0; dz = -1 }
    const len = Math.hypot(dx, dz) || 1
    dx /= len; dz /= len
    const sin = Math.sin(this.yaw), cos = Math.cos(this.yaw)
    const wx = dx * cos + dz * sin
    const wz = -dx * sin + dz * cos
    this.dodgeDir.set(wx, 0, wz)
    this.dodgeTime = 0.2
    this.dodgeCooldown = 0.85
    this.invuln = Math.max(this.invuln, 0.34)
    this.cancelCharge()
    this.blocking = false
    this.attackState = 'idle'
    sound.dodge()
    this.game?.onDodge()
  }

  shove() {
    if (!this.alive || this.shoveCooldown > 0 || this.executing > 0) return
    if (this.attackState === 'windup' || this.attackState === 'active') return
    this.shoveTime = 0.28
    this.shoveCooldown = 0.9
    this.shoveHit = false
    this.cancelCharge()
    sound.whooshHeavy()
    this.game?.onShove()
  }

  shake(amount) {
    this.shakeAmt = Math.min(0.6, this.shakeAmt + amount)
  }

  update(dt) {
    this.time += dt
    this.hurtFlash = Math.max(0, this.hurtFlash - dt * 2.5)
    this.shakeAmt = Math.max(0, this.shakeAmt - dt * 1.7)
    this.recoil = Math.max(0, this.recoil - dt * 6)
    this.rigSway.x = damp(this.rigSway.x, 0, 6, dt)
    this.rigSway.y = damp(this.rigSway.y, 0, 6, dt)
    if (this.dodgeCooldown > 0) this.dodgeCooldown -= dt
    if (this.shoveCooldown > 0) this.shoveCooldown -= dt
    if (this.invuln > 0) this.invuln -= dt
    if (this.swapTime > 0) this.swapTime -= dt
    if (this.comboTimer > 0) this.comboTimer -= dt
    if (this.blocking) this.blockTime += dt

    if (!this.alive) {
      this.deadTime += dt
      this.updateCamera(dt)
      this.updateWeapon(dt)
      return
    }

    if (this.executing > 0) {
      this.executing -= dt
      this.updateWeapon(dt)
      this.updateCamera(dt)
      return
    }

    if (this.charging) {
      this.chargeTime = Math.min(1.6, this.chargeTime + dt)
      this.game?.onCharge(this.chargeTime)
    }

    // dodge motion
    if (this.dodgeTime > 0) {
      this.dodgeTime -= dt
      const speed = 10.5 * (this.dodgeTime / 0.2) + 2.5
      this.pos.x += this.dodgeDir.x * speed * dt
      this.pos.z += this.dodgeDir.z * speed * dt
      if (chance(0.4)) {
        this.gore.blood.spawn(this.pos.x, 0.08, this.pos.z, { vy: 0.4, chaos: 0.3, size: 0.5, life: 0.5 })
      }
    } else {
      const input = this.moveInput
      let dx = input.x, dz = input.z
      const len = Math.hypot(dx, dz)
      if (len > 1) { dx /= len; dz /= len }
      const sin = Math.sin(this.yaw), cos = Math.cos(this.yaw)
      const wx = dx * cos + dz * sin
      const wz = -dx * sin + dz * cos
      let speed = this.moveSpeed
      if (this.charging) speed *= 0.55
      if (this.blocking) speed *= 0.5
      if (this.attackState === 'windup' || this.attackState === 'active') speed *= 0.28
      if (this.shoveTime > 0) speed *= 0.5
      this.vel.x = damp(this.vel.x, wx * speed, 14, dt)
      this.vel.z = damp(this.vel.z, wz * speed, 14, dt)
      this.pos.x += this.vel.x * dt
      this.pos.z += this.vel.z * dt
      const moveAmt = Math.hypot(this.vel.x, this.vel.z)
      if (moveAmt > 0.4) {
        this.walkPhase += dt * moveAmt * 1.6
        this.stepTimer -= dt
        if (this.stepTimer <= 0) { this.stepTimer = 0.34; sound.step() }
      }
    }

    // arena bounds
    const r = Math.hypot(this.pos.x, this.pos.z)
    const limit = ARENA_RADIUS - 0.7
    if (r > limit) {
      this.pos.x *= limit / r
      this.pos.z *= limit / r
      this.vel.multiplyScalar(0.5)
    }

    // attack timing
    if (this.attackState !== 'idle') {
      this.attackT += dt
      if (this.attackState === 'windup' && this.attackT >= this.attackWindup) {
        this.attackState = 'active'
        this.attackT = 0
      } else if (this.attackState === 'active') {
        this.sampleHit(dt)
        if (this.attackT >= this.attackActive) {
          this.attackState = 'recover'
          this.attackT = 0
        }
      } else if (this.attackState === 'recover' && this.attackT >= this.attackRecover) {
        this.attackState = 'idle'
        this.attackT = 0
        this.comboTimer = 0.5
      }
    }

    // shove hit
    if (this.shoveTime > 0) {
      this.shoveTime -= dt
      this.kick = Math.sin((1 - this.shoveTime / 0.28) * Math.PI)
      if (!this.shoveHit && this.shoveTime < 0.2) {
        this.shoveHit = true
        this.game?.playerShove(this)
      }
    } else this.kick = Math.max(0, this.kick - dt * 5)

    // passive blood drip from dirty weapon
    if (this.weaponModel?.userData.stain?.visible && chance(dt * 2.2) && this.weaponModel) {
      this.getWeaponPoints(this.baseA, this.baseB)
      this.gore.blood.spawn(this.baseB.x, this.baseB.y, this.baseB.z, { vy: -0.4, chaos: 0.1, size: 0.55, life: 0.5, gravity: 1 })
    }

    this.updateWeapon(dt)
    this.updateCamera(dt)
  }

  getWeaponPoints(base, tip) {
    if (!this.weaponModel) return
    this.weaponModel.updateWorldMatrix(true, false)
    const u = this.weaponModel.userData
    base.set(0, u.base, 0)
    tip.set(0, u.tip, 0)
    this.weaponModel.localToWorld(base)
    this.weaponModel.localToWorld(tip)
  }

  sampleHit(dt) {
    const cfg = this.stats[this.attackKind]
    this.getWeaponPoints(this.tipA, this.tipB)
    // also sample previous frame's path for fast swings
    const a = this.tipA, b = this.tipB
    const hitPoint = new THREE.Vector3()
    const dir = new THREE.Vector3()
    this.game?.playerSwing(this, a, b, this.attackKind, this.attackDamage, this.stats.type, this.attackHitRadius, this.hitSet)
    // blade trail
    if (this.attackState === 'active') {
      this.trail.push(a, b, this.time)
    }
    this.recoil = Math.max(this.recoil, 0)
  }

  updateWeapon(dt) {
    if (!this.weaponModel) return
    let px = this.rigBase.x, py = this.rigBase.y, pz = this.rigBase.z
    let rx = -0.15, ry = 0.35, rz = -0.32
    if (this.weaponId === 'hammer') {
      rx = -0.28; ry = -0.18; rz = 0.16
    }

    const walkAmt = clamp(Math.hypot(this.vel.x, this.vel.z) / 5, 0, 1)
    const bob = Math.sin(this.walkPhase) * 0.016 * walkAmt
    const bob2 = Math.abs(Math.cos(this.walkPhase)) * 0.012 * walkAmt
    px += Math.sin(this.walkPhase * 0.5) * 0.012 * walkAmt + this.rigSway.x
    py += bob + bob2 + this.rigSway.y + Math.sin(this.time * 1.7) * 0.004
    pz += Math.cos(this.walkPhase) * 0.008 * walkAmt

    // charge pose
    if (this.charging) {
      const t = clamp(this.chargeTime / 1.0, 0, 1)
      const e = easeOutCubic(t)
      if (this.weaponId === 'hammer') {
        rx = lerp(-0.28, -0.95, e)
        ry = lerp(-0.18, 0.35, e)
        rz = lerp(0.16, -0.25, e)
        px = lerp(px, 0.5, e)
        py = lerp(py, -0.3, e)
      } else {
        rx = lerp(-0.15, -0.7, e)
        ry = lerp(0.35, 1.15, e)
        rz = lerp(-0.32, -0.85, e)
        px = lerp(px, 0.58, e)
        py = lerp(py, -0.34, e)
      }
      rx += Math.sin(this.time * 30) * 0.008 * e
    }

    // attack poses
    if (this.attackState !== 'idle') {
      const kind = this.attackKind
      const w = this.attackWindup, a = this.attackActive, rc = this.attackRecover
      let t = 0
      let phase = ''
      if (this.attackState === 'windup') { t = this.attackT / w; phase = 'w' }
      else if (this.attackState === 'active') { t = this.attackT / a; phase = 'a' }
      else { t = this.attackT / rc; phase = 'r' }
      const idx = this.attackIndex
      const swingPose = this.getSwingPose(kind, idx, phase, t)
      if (swingPose) {
        px = swingPose.px; py = swingPose.py; pz = swingPose.pz
        rx = swingPose.rx; ry = swingPose.ry; rz = swingPose.rz
      }
    }

    if (this.blocking) {
      this.blockingVisual = damp(this.blockingVisual, 1, 18, dt)
    } else {
      this.blockingVisual = damp(this.blockingVisual, 0, 14, dt)
    }
    if (this.blockingVisual > 0.01) {
      const bl = this.blockingVisual
      px = lerp(px, 0.22, bl)
      py = lerp(py, -0.32, bl)
      pz = lerp(pz, -0.5, bl)
      rx = lerp(rx, 0.05, bl)
      ry = lerp(ry, 0.9, bl)
      rz = lerp(rz, 1.05, bl)
    }

    if (this.shoveTime > 0) {
      py -= this.kick * 0.1
      pz -= this.kick * 0.16
      rx -= this.kick * 0.5
    }

    if (this.swapTime > 0) {
      py -= Math.sin((1 - this.swapTime / 0.32) * Math.PI) * 0.4
      rx -= Math.sin((1 - this.swapTime / 0.32) * Math.PI) * 0.6
    }

    if (this.executing > 0) {
      pz -= 0.2
      rx += 0.5
    }

    const dampK = 1 - Math.exp(-22 * dt)
    this.rig.position.x += (px - this.rig.position.x) * dampK
    this.rig.position.y += (py - this.rig.position.y) * dampK
    this.rig.position.z += (pz - this.rig.position.z) * dampK
    this.rig.rotation.x += (rx - this.rig.rotation.x) * dampK
    this.rig.rotation.y += (ry - this.rig.rotation.y) * dampK
    this.rig.rotation.z += (rz - this.rig.rotation.z) * dampK

    // trail update
    const active = this.attackState === 'active'
    this.trail.update(this.time, active)

    // stain + drip
    if (this.weaponModel.userData.stain) {
      this.weaponModel.userData.stain.visible = (this.bloodied || 0) > 0
    }
  }

  getSwingPose(kind, idx, phase, t) {
    const heavy = kind === 'heavy'
    const sword = this.weaponId === 'sword'
    let w, a, r
    let start, mid, end
    if (sword) {
      if (idx === 2) {
        // overhead chop
        start = { px: 0.52, py: -0.3, pz: -0.52, rx: -0.8, ry: 0.35, rz: -0.35 }
        w = { px: 0.58, py: -0.12, pz: -0.5, rx: -1.35, ry: 0.2, rz: -0.15 }
        end = { px: 0.18, py: -0.55, pz: -0.72, rx: 0.95, ry: -0.1, rz: 0.1 }
        r = { px: 0.34, py: -0.45, pz: -0.62, rx: 0.25, ry: 0.15, rz: -0.2 }
      } else {
        const s = idx === 0 ? 1 : -1
        start = { px: 0.42, py: -0.42, pz: -0.58, rx: -0.15, ry: 0.35 * s, rz: -0.32 }
        w = { px: 0.42 + 0.2 * s, py: -0.3, pz: -0.5, rx: -0.35, ry: 1.1 * s, rz: -0.7 * s }
        end = { px: 0.2 - 0.1 * s, py: -0.38, pz: -0.68, rx: 0.15, ry: -0.95 * s, rz: 0.45 * s }
        r = { px: 0.32, py: -0.42, pz: -0.6, rx: -0.05, ry: -0.25 * s, rz: 0.05 }
      }
      if (heavy) {
        w = { ...w, rx: w.rx - 0.5, ry: w.ry + 0.35, py: w.py - 0.05 }
        end = { ...end, px: end.px - 0.08, ry: end.ry - 0.25 }
      }
    } else {
      if (idx === 2 || heavy) {
        start = { px: 0.44, py: -0.36, pz: -0.6, rx: -0.28, ry: -0.18, rz: 0.16 }
        w = { px: 0.5, py: 0.02, pz: -0.44, rx: -1.15, ry: 0.05, rz: 0.05 }
        end = { px: 0.22, py: -0.62, pz: -0.66, rx: 0.95, ry: -0.15, rz: 0.05 }
        r = { px: 0.36, py: -0.48, pz: -0.6, rx: 0.3, ry: -0.1, rz: 0.12 }
      } else {
        const s = idx === 0 ? 1 : -1
        start = { px: 0.44, py: -0.36, pz: -0.6, rx: -0.28, ry: -0.18, rz: 0.16 }
        w = { px: 0.55, py: -0.2, pz: -0.46, rx: -0.5, ry: 0.9 * s, rz: -0.55 * s }
        end = { px: 0.2, py: -0.5, pz: -0.7, rx: 0.35, ry: -1.0 * s, rz: 0.55 * s }
        r = { px: 0.36, py: -0.44, pz: -0.62, rx: 0.1, ry: -0.2 * s, rz: 0.18 }
      }
    }
    if (phase === 'w') {
      const e = easeOutQuint(t)
      return this.mixPose(start, w, e)
    }
    if (phase === 'a') {
      const e = easeOutQuint(Math.min(1, t * 1.25))
      return this.mixPose(w, end, e)
    }
    const e = easeInOutQuad(t)
    return this.mixPose(end, r, e)
  }

  mixPose(a, b, t) {
    return {
      px: lerp(a.px, b.px, t), py: lerp(a.py, b.py, t), pz: lerp(a.pz, b.pz, t),
      rx: lerp(a.rx, b.rx, t), ry: lerp(a.ry, b.ry, t), rz: lerp(a.rz, b.rz, t)
    }
  }

  updateCamera(dt) {
    const bobAmt = this.alive ? clamp(Math.hypot(this.vel.x, this.vel.z) / 5, 0, 1) : 0
    const bobY = Math.abs(Math.sin(this.walkPhase)) * 0.045 * bobAmt
    const bobX = Math.sin(this.walkPhase * 0.5) * 0.02 * bobAmt
    let eyeY = 1.68 - bobY + Math.sin(this.time * 1.6) * 0.006
    let roll = Math.sin(this.walkPhase * 0.5) * 0.006 * bobAmt
    if (!this.alive) {
      const t = clamp(this.deadTime / 1.1, 0, 1)
      eyeY = lerp(1.68, 0.38, easeOutCubic(t))
      roll = lerp(0, 1.25, easeOutCubic(t))
    }
    if (this.dodgeTime > 0) roll += 0.05 * (this.dodgeTime / 0.2)
    if (this.charging) {
      const t = clamp(this.chargeTime / 1.0, 0, 1)
      eyeY -= 0.02 * t
      roll += Math.sin(this.time * 40) * 0.0025 * t
    }
    // camera kick from attacks
    const kick = this.attackState === 'active' ? 0.012 : 0
    const shake = this.shakeAmt
    const sx = (Math.random() - 0.5) * shake * 0.3
    const sy = (Math.random() - 0.5) * shake * 0.3
    const sz = (Math.random() - 0.5) * shake * 0.15
    this.camera.position.set(
      this.pos.x + bobX + sx,
      eyeY + sy,
      this.pos.z + sz
    )
    if (this.attackState === 'active') {
      const target = this.attackKind === 'heavy' ? 0.05 : 0.026
      this.camKick.x = lerp(this.camKick.x, target, 0.4)
    } else {
      this.camKick.x = damp(this.camKick.x, 0, 8, dt)
    }
    this.camera.rotation.order = 'YXZ'
    this.camera.rotation.y = this.yaw
    this.camera.rotation.x = this.pitch + this.camKick.x + (Math.random() - 0.5) * shake * 0.12
    this.camera.rotation.z = roll + (Math.random() - 0.5) * shake * 0.15
  }

  takeDamage(amount, attacker, weaponKind, dirVec) {
    if (!this.alive || this.invuln > 0 || this.executing > 0) return
    this.game?.clearRegen?.()
    let dmg = amount
    let parried = false
    const facing = this.blocking && Math.abs(this.yaw - Math.atan2(attacker.root.position.x - this.pos.x, attacker.root.position.z - this.pos.z)) < 2.2
    // proper facing check, accounting for yaw wrap
    let toAttacker = Math.atan2(attacker.root.position.x - this.pos.x, attacker.root.position.z - this.pos.z)
    let diff = toAttacker - this.yaw
    while (diff > Math.PI) diff -= TAU
    while (diff < -Math.PI) diff += TAU
    const blockingFront = this.blocking && Math.abs(diff) < 1.35
    if (blockingFront) {
      if (this.blockTime < this.parryWindow) {
        parried = true
        dmg = 0
        this.game?.onParry(attacker)
        sound.parry()
        this.shake(0.22)
        this.blockTime = 0.6
        this.invuln = Math.max(this.invuln, 0.35)
      } else {
        dmg = amount * 0.14
        sound.block()
        this.shake(0.12)
        this.blockTime = 0.6
      }
    }
    if (dmg > 0) {
      this.health = Math.max(0, this.health - dmg)
      this.hurtFlash = Math.min(1, this.hurtFlash + dmg / 40)
      this.shake(0.2 + dmg * 0.008)
      sound.playerHurt()
      this.game?.onPlayerHurt(dmg, attacker, dirVec)
      this.bloodied = (this.bloodied || 0) + 1
      if (this.health <= 0) this.die(attacker)
    }
    return { blocked: blockingFront, parried }
  }

  die(attacker) {
    if (!this.alive) return
    this.alive = false
    this.deadTime = 0
    this.blocking = false
    this.charging = false
    this.attackState = 'idle'
    this.game?.onPlayerDeath(attacker)
    sound.scream(0.75)
    sound.deathRattle()
    this.gore.blood.burst(new THREE.Vector3(this.pos.x, 1.1, this.pos.z), { count: 30, chaos: 2.5, size: 1.1 })
    this.gore.groundSplash({ x: this.pos.x, y: 0, z: this.pos.z })
  }

  eyePosition(out = new THREE.Vector3()) {
    return out.set(this.pos.x, 1.62, this.pos.z)
  }

  get blockingActive() { return this.blocking }
}

